async def actualizar_producto(
    id_producto: str,
    data: ProductoUpdate,
    user: UsuarioActual = Depends(
        require_roles(
            "PROVEEDOR",
            "OPERARIO"
        )
    )
):

    await AccesoService.verificar_producto(
        user,
        id_producto
    )

    if user.es_operario:

        if data.model_fields_set - {"id_rack"}:

            raise HTTPException(
                status_code=403,
                detail=(
                    "El operario solo puede cambiar "
                    "el rack de referencia (id_rack)"
                )
            )

        if data.id_rack:

            await AccesoService.verificar_rack(
                user,
                data.id_rack
            )

    else:

        # El proveedor no gestiona racks: se conserva
        # el rack de referencia actual.
        data = ProductoUpdate(
            **data.model_dump(
                exclude_unset=True,
                exclude={"id_rack"}
            )
        )

    return await (
        ProductoService.actualizar(
            id_producto,
            data
        )
    )


# ============================================================
# ELIMINAR (PROVEEDOR, los suyos)
# ============================================================

errors_direct.action:
if user.es_operario:

    if data.model_fields_set - {"id_rack"}:

        raise HTTPException(
            status_code=403,
            detail=(
                "El operario solo puede cambiar "
                "el rack de referencia (id_rack)"
            )
        )

    if data.id_rack:

        await AccesoService.verificar_rack(
            user,
