def _json_safe_value(
    value
):

    try:

        if pd.isna(value):
            return None

    except (
        TypeError,
        ValueError
    ):

        pass

    if hasattr(
        value,
        "item"
    ):

        try:
            return value.item()

        except Exception:
            pass

    return value

def _features_to_json(
    features: dict
) -> dict:

    return {

        key:
            _json_safe_value(
                value
            )

        for key, value
        in features.items()
    }


