def _crear_history_dataframe(
    historial: list
) -> pd.DataFrame:

    if not historial:

        raise ValueError(
            "No existe historial de demanda "
            "para el inventario indicado."
        )

    history_df = pd.DataFrame(
        historial
    )

    if history_df.empty:

        raise ValueError(
            "El historial de demanda está vacío."
        )

    required_columns = {
        "fecha",
        "demanda"
    }

    missing_columns = (

        required_columns

        - set(
            history_df.columns
        )
    )

    if missing_columns:

        raise ValueError(
            "DemandHistory no devolvió "
            "las columnas necesarias: "
            + ", ".join(
                sorted(
                    missing_columns
                )
            )
        )

    history_df[
        "fecha"
    ] = pd.to_datetime(
        history_df[
            "fecha"
        ]
    )

    return history_df


# ============================================================
# FECHA BASE
# ============================================================

def _obtener_fecha_base(
    history_df: pd.DataFrame
) -> pd.Timestamp:

    fecha_base = (
        pd.to_datetime(
            history_df[
                "fecha"
            ]
        )
        .max()
    )

    if pd.isna(
        fecha_base
    ):

        raise ValueError(
            "No se pudo determinar "
            "la fecha base."
        )

    return fecha_base


# ============================================================
# DEBUG HISTORY
# ============================================================

async def debug_context(

    id_inventario: str

):

    try:

        demand_history = (
            DemandHistory()
        )

        historial = await (
            demand_history
            .obtener_ultimos_dias(

                id_inventario=
                    id_inventario,

                dias=
                    30
            )
        )

        history_df = (
            _crear_history_dataframe(
                historial
            )
        )

        fecha_base = (
            _obtener_fecha_base(
                history_df
            )
        )

        context_builder = (
            MLContextBuilder()
        )

        resultado = await (
            context_builder.build(

                id_inventario=
                    id_inventario,

                fecha_base=
                    fecha_base.to_pydatetime()
            )
        )

        return {

            "mensaje":
                "Contexto ML generado correctamente",

            "id_inventario":
                id_inventario,

            "fecha_base_forecast":
                fecha_base.strftime(
                    "%Y-%m-%d"
                ),

            **resultado
        }

    except ValueError as exc:

        raise HTTPException(
            status_code=404,
            detail=str(exc)
        )

    except Exception as exc:

        raise HTTPException(
            status_code=500,
            detail=(
                "Error construyendo contexto "
                f"ML: {str(exc)}"
            )
        )


