    if await InventarioRepository().obtener_por_producto(
        id_producto
    ):

        raise HTTPException(
            status_code=409,
            detail=(
                "El producto tiene inventarios; "
                "no puede eliminarse"
            )
        )

    return await (
        ProductoService.eliminar(
            id_producto
        )
    )

