def _no_autorizado(
    detalle: str
) -> HTTPException:

    return HTTPException(
        status_code=(
            status.HTTP_401_UNAUTHORIZED
        ),
        detail=detalle,
        headers={
            "WWW-Authenticate":
                "Bearer"
        }
    )

async def get_current_user(
    credentials: Optional[
        HTTPAuthorizationCredentials
    ] = Depends(
        bearer_scheme
    )
) -> UsuarioActual:

    if (
        credentials is None
        or
        not credentials.credentials
    ):

        raise _no_autorizado(
            "No autenticado"
        )

    try:

        payload = decode_access_token(
            credentials.credentials
        )

    except jwt.ExpiredSignatureError:

        raise _no_autorizado(
            "Token expirado"
        )

    except jwt.InvalidTokenError:

        raise _no_autorizado(
            "Token inválido"
        )

    sub = payload.get(
        "sub"
    )

    if not sub:

        raise _no_autorizado(
            "Token inválido"
        )

    rol = payload.get(
        "rol"
    )

    # --------------------------------------------------------
    # TOKEN ANTIGUO / EMPRESA
    # --------------------------------------------------------

    if rol is None:

        if payload.get("type") not in (
            None,
            "empresa"
        ):

            raise _no_autorizado(
                "Token inválido"
            )

        rol = ROL_EMPRESA

    if rol == ROL_EMPRESA:

        return UsuarioActual(
            rol=ROL_EMPRESA,
            id_empresa=(
                payload.get("id_empresa")
                or
                sub
            )
        )

    # --------------------------------------------------------
    # OPERARIO
    # --------------------------------------------------------

    if rol == ROL_OPERARIO:

        operario = await (
            OperarioRepository
            .obtener_por_id(
                sub
            )
        )

        if not operario:

            raise _no_autorizado(
                "Operario no encontrado"
            )

        if (
            str(operario.get("estado", "")).upper()
            != "ACTIVO"
        ):

            raise _prohibido(
                "Operario inactivo"
            )

        return UsuarioActual(

            rol=ROL_OPERARIO,

            id_empresa=
                operario["id_empresa"],

            id_operario=
                operario["id_operario"],

            id_almacen=
                operario.get("id_almacen"),

            debe_cambiar_password=bool(
                operario.get(
                    "debe_cambiar_password",
                    False
                )
            )
        )

    # --------------------------------------------------------
    # PROVEEDOR
    # --------------------------------------------------------

    if rol == ROL_PROVEEDOR:

        proveedor = await (
            ProveedorRepository()
            .obtener_por_id(
                sub
            )
        )

        if not proveedor:

            raise _no_autorizado(
                "Proveedor no encontrado"
            )

        if (
            str(proveedor.get("estado", "")).upper()
            != "ACTIVO"
        ):

            raise _prohibido(
                "Proveedor inactivo"
            )

        return UsuarioActual(

            rol=ROL_PROVEEDOR,

            id_empresa=
                proveedor["id_empresa"],

            id_proveedor=
                proveedor["id_proveedor"],

            debe_cambiar_password=bool(
                proveedor.get(
                    "debe_cambiar_password",
                    False
                )
            )
        )

    raise _no_autorizado(
        "Token inválido"
    )


