# ============================================================
# NORMALIZAR FECHA
# ============================================================

def _inicio_dia(
    fecha: date | datetime
) -> datetime:

    if isinstance(
        fecha,
        datetime
    ):

        fecha = fecha.date()

    return datetime.combine(
        fecha,
        time.min,
        tzinfo=timezone.utc
    )

def _fin_dia(
    fecha: date | datetime
) -> datetime:

    if isinstance(
        fecha,
        datetime
    ):

        fecha = fecha.date()

    return datetime.combine(
        fecha,
        time.max,
        tzinfo=timezone.utc
    )

# ============================================================
# HISTORIAL POR INVENTARIO
# ============================================================

async def obtener_historial(
    self,
    id_inventario: str,
    dias: int = 400,
    fecha_fin: Optional[
        date | datetime
    ] = None
) -> pd.DataFrame:

    if dias <= 0:

        raise ValueError(
            "dias debe ser mayor que 0."
        )

    # --------------------------------------------------------
    # VALIDAR INVENTARIO
    # --------------------------------------------------------

    inventario = (
        await self.inventario_repository
        .obtener_por_id(
            id_inventario
        )
    )

    if inventario is None:

        raise ValueError(
            "No existe el inventario "
            f"{id_inventario}."
        )

    # --------------------------------------------------------
    # FECHA FINAL
    # --------------------------------------------------------

    if fecha_fin is None:

        fecha_final_date = (
            datetime.now(
                timezone.utc
            )
            .date()
        )

    elif isinstance(
        fecha_fin,
        datetime
    ):

        fecha_final_date = (
            fecha_fin.date()
        )

    else:

        fecha_final_date = (
            fecha_fin
        )

    # --------------------------------------------------------
    # FECHA INICIAL
    # --------------------------------------------------------

    fecha_inicial_date = (
        fecha_final_date
        - timedelta(
            days=dias - 1
        )
    )

    fecha_inicio_query = (
        self._inicio_dia(
            fecha_inicial_date
        )
    )

    fecha_fin_query = (
        self._fin_dia(
            fecha_final_date
        )
    )

    # --------------------------------------------------------
    # CONSULTAR MONGODB
    # --------------------------------------------------------

    consumo = (
        await self.movimiento_repository
        .obtener_consumo_diario_inventario(
            id_inventario=
                id_inventario,

            fecha_inicio=
                fecha_inicio_query,

            fecha_fin=
                fecha_fin_query
        )
    )

    # --------------------------------------------------------
    # CALENDARIO COMPLETO
    # --------------------------------------------------------

    fechas = pd.date_range(
        start=fecha_inicial_date,
        end=fecha_final_date,
        freq="D"
    )

    historial = pd.DataFrame(
        {
            "fecha":
                fechas
        }
    )

    # Por defecto no hubo consumo.
    historial[
        "demanda"
    ] = 0.0

    # --------------------------------------------------------
    # SI EXISTEN MOVIMIENTOS
    # --------------------------------------------------------

    if consumo:

        consumo_df = pd.DataFrame(
            consumo
        )

        consumo_df[
            "fecha"
        ] = pd.to_datetime(
            consumo_df[
                "fecha"
            ]
        )

        consumo_df[
            "cantidad"
        ] = pd.to_numeric(
            consumo_df[
                "cantidad"
            ],
            errors="coerce"
        ).fillna(
            0
        )

        consumo_df = (
            consumo_df[
                [
                    "fecha",
                    "cantidad"
                ]
            ]
            .rename(
                columns={
                    "cantidad":
                        "demanda"
                }
            )
        )

        # ----------------------------------------------------
        # MERGE
        # ----------------------------------------------------

        historial = (
            historial[
                [
                    "fecha"
                ]
            ]
            .merge(
                consumo_df,
                how="left",
                on="fecha"
            )
        )

        historial[
            "demanda"
        ] = (
            historial[
                "demanda"
            ]
            .fillna(
                0
            )
            .astype(
                float
            )
        )

    # --------------------------------------------------------
    # ORDEN
    # --------------------------------------------------------

    historial = (
        historial
        .sort_values(
            "fecha"
        )
        .reset_index(
            drop=True
        )
    )

    return historial

# ============================================================
# HISTORIAL COMPLETO DISPONIBLE
# ============================================================

async def obtener_historial_completo(
    self,
    id_inventario: str
) -> pd.DataFrame:

    inventario = (
        await self.inventario_repository
        .obtener_por_id(
            id_inventario
        )
    )

    if inventario is None:

        raise ValueError(
            "Inventario no encontrado."
        )

    movimientos = (
        await self.movimiento_repository
        .obtener_por_inventario(
            id_inventario
        )
    )

    salidas = [

        movimiento

        for movimiento in movimientos

        if (
            movimiento.get(
                "tipo_movimiento"
            )
            == "SALIDA"
        )

        and movimiento.get(
            "fecha_hora"
        )
    ]

    if not salidas:

        return pd.DataFrame(
            columns=[
                "fecha",
                "demanda"
            ]
        )

    fecha_minima = min(
        movimiento[
            "fecha_hora"
        ]
        for movimiento in salidas
    )

    fecha_maxima = datetime.now(
        timezone.utc
    )

    dias = (
        fecha_maxima.date()
        - fecha_minima.date()
    ).days + 1

    return await self.obtener_historial(
        id_inventario=
            id_inventario,

        dias=
            dias,

        fecha_fin=
            fecha_maxima
    )

# ============================================================
# INFORMACION DEL HISTORIAL
# ============================================================

async def obtener_ultimos_dias(
    self,
    id_inventario: str,
    dias: int
) -> List[Dict[str, Any]]:

    historial = (
        await self.obtener_historial(
            id_inventario=
                id_inventario,

            dias=
                dias
        )
    )

    resultado = []

    for _, row in (
        historial.iterrows()
    ):

        resultado.append(
            {
                "fecha":
                    row[
                        "fecha"
                    ]
                    .date()
                    .isoformat(),

                "demanda":
                    float(
                        row[
                            "demanda"
                        ]
                    )
            }
        )

    return resultado

def _safe_float(
    value: Any,
    default: float = 0.0
) -> float:

    try:

        result = float(
            value
        )

        if np.isnan(result):

            return default

        if np.isinf(result):

            return default

        return result

    except (
        TypeError,
        ValueError
    ):

        return default

# ============================================================
# DIVISION SEGURA
# ============================================================

def _safe_divide(
    cls,
    numerator: float,
    denominator: float,
    default: float = 0.0
) -> float:

    numerator = cls._safe_float(
        numerator
    )

    denominator = cls._safe_float(
        denominator
    )

    if abs(
        denominator
    ) < cls.EPSILON:

        return default

    return (
        numerator
        / denominator
    )

# ============================================================
# NORMALIZAR HISTORIAL
# ============================================================

def _prepare_history(
    history: pd.DataFrame
) -> pd.DataFrame:

    if not isinstance(
        history,
        pd.DataFrame
    ):

        raise TypeError(
            "history debe ser un pandas.DataFrame."
        )

    if history.empty:

        raise ValueError(
            "El historial de demanda está vacío."
        )

    required = {
        "fecha",
        "demanda"
    }

    missing = (
        required
        - set(history.columns)
    )

    if missing:

        raise ValueError(
            "El historial debe contener las columnas: "
            "fecha y demanda."
        )

    df = history[
        [
            "fecha",
            "demanda"
        ]
    ].copy()

    df[
        "fecha"
    ] = pd.to_datetime(
        df["fecha"],
        errors="coerce"
    )

    df[
        "demanda"
    ] = pd.to_numeric(
        df["demanda"],
        errors="coerce"
    ).fillna(
        0.0
    )

    df = (
        df
        .dropna(
            subset=[
                "fecha"
            ]
        )
        .sort_values(
            "fecha"
        )
        .drop_duplicates(
            subset=[
                "fecha"
            ],
            keep="last"
        )
        .reset_index(
            drop=True
        )
    )

    if df.empty:

        raise ValueError(
            "No existen fechas válidas "
            "en el historial."
        )

    return df

# ============================================================
# OBTENER SERIE
# ============================================================

def _series(
    cls,
    history: pd.DataFrame
) -> pd.Series:

    df = cls._prepare_history(
        history
    )

    return (
        df[
            "demanda"
        ]
        .astype(float)
        .reset_index(
            drop=True
        )
    )

# ============================================================
# OBTENER FECHA BASE
# ============================================================

def _base_date(
    cls,
    history: pd.DataFrame
) -> pd.Timestamp:

    df = cls._prepare_history(
        history
    )

    return pd.Timestamp(
        df[
            "fecha"
        ].iloc[-1]
    )

# ============================================================
# LAG
#
# lag_1 = demanda del último día disponible
# lag_7 = demanda de hace 7 días
# ============================================================

def _lag(
    series: pd.Series,
    lag: int
) -> float:

    if lag <= 0:

        raise ValueError(
            "lag debe ser mayor que 0."
        )

    if len(series) < lag:

        return np.nan

    return float(
        series.iloc[
            -lag
        ]
    )

# ============================================================
# ULTIMOS N VALORES
# ============================================================

def _last_values(
    series: pd.Series,
    window: int
) -> pd.Series:

    if window <= 0:

        raise ValueError(
            "window debe ser mayor que 0."
        )

    if series.empty:

        return pd.Series(
            dtype=float
        )

    return (
        series
        .iloc[
            -window:
        ]
        .astype(float)
    )

# ============================================================
# ROLLING MEAN
# ============================================================

def _rolling_mean(
    cls,
    series: pd.Series,
    window: int
) -> float:

    values = cls._last_values(
        series,
        window
    )

    if len(values) < window:

        return np.nan

    return float(
        values.mean()
    )

# ============================================================
# ROLLING STD
# ============================================================

def _rolling_std(
    cls,
    series: pd.Series,
    window: int
) -> float:

    values = cls._last_values(
        series,
        window
    )

    if len(values) < window:

        return np.nan

    return float(
        values.std(
            ddof=0
        )
    )

# ============================================================
# ROLLING MAX
# ============================================================

def _rolling_max(
    cls,
    series: pd.Series,
    window: int
) -> float:

    values = cls._last_values(
        series,
        window
    )

    if len(values) < window:

        return np.nan

    return float(
        values.max()
    )

# ============================================================
# EWMA
# ============================================================

def _ewma(
    cls,
    series: pd.Series,
    span: int
) -> float:

    if series.empty:

        return np.nan

    value = (
        series
        .astype(float)
        .ewm(
            span=span,
            adjust=False
        )
        .mean()
        .iloc[-1]
    )

    return float(
        value
    )

# ============================================================
# ZERO RATIO
# ============================================================

def _zero_ratio(
    cls,
    series: pd.Series,
    window: int
) -> float:

    values = cls._last_values(
        series,
        window
    )

    if len(values) < window:

        return np.nan

    return float(
        (
            values == 0
        ).mean()
    )

# ============================================================
# DAYS SINCE SALE
# ============================================================

def _days_since_sale(
    series: pd.Series
) -> float:

    if series.empty:

        return np.nan

    values = (
        series
        .astype(float)
        .to_numpy()
    )

    positive_indices = np.where(
        values > 0
    )[0]

    if len(
        positive_indices
    ) == 0:

        return float(
            len(values)
        )

    last_index = int(
        positive_indices[-1]
    )

    return float(
        len(values)
        - 1
        - last_index
    )

# ============================================================
# SALE RATE
# ============================================================

def _sale_rate(
    cls,
    series: pd.Series,
    window: int
) -> float:

    values = cls._last_values(
        series,
        window
    )

    if len(values) < window:

        return np.nan

    return float(
        (
            values > 0
        ).mean()
    )

# ============================================================
# GROWTH STREAK
# ============================================================

def _growth_streak_3(
    cls,
    series: pd.Series
) -> float:

    values = cls._last_values(
        series,
        4
    )

    if len(values) < 4:

        return np.nan

    diffs = (
        values
        .diff()
        .dropna()
    )

    return float(
        (
            diffs > 0
        ).all()
    )

# ============================================================
# PEAK COUNT
# ============================================================

def _peak_count_7(
    cls,
    series: pd.Series
) -> float:

    values = cls._last_values(
        series,
        7
    )

    if len(values) < 7:

        return np.nan

    mean_28 = cls._rolling_mean(
        series,
        28
    )

    if np.isnan(
        mean_28
    ):

        return np.nan

    return float(
        (
            values > mean_28
        ).sum()
    )

# ============================================================
# INCREMENTOS
# ============================================================

def _dow_mean(
    cls,
    history: pd.DataFrame,
    target_date: pd.Timestamp,
    weeks: int
) -> float:

    df = cls._prepare_history(
        history
    )

    target_dow = (
        target_date.dayofweek
    )

    filtered = df[
        df[
            "fecha"
        ].dt.dayofweek
        == target_dow
    ]

    filtered = (
        filtered.tail(
            weeks
        )
    )

    if len(
        filtered
    ) < 1:

        return np.nan

    return float(
        filtered[
            "demanda"
        ].mean()
    )

# ============================================================
# DOW STD
# ============================================================

def _dow_std(
    cls,
    history: pd.DataFrame,
    target_date: pd.Timestamp,
    weeks: int
) -> float:

    df = cls._prepare_history(
        history
    )

    target_dow = (
        target_date.dayofweek
    )

    filtered = df[
        df[
            "fecha"
        ].dt.dayofweek
        == target_dow
    ].tail(
        weeks
    )

    if len(filtered) < 2:

        return np.nan

    return float(
        filtered[
