def validate_features(
    self,
    data: Dict[
        str,
        Any
    ]
) -> None:

    if not isinstance(
        data,
        dict
    ):

        raise TypeError(
            "data debe ser un diccionario."
        )

    missing = [

        feature

        for feature
        in self.features

        if feature
        not in data
    ]

    if missing:

        raise ValueError(
            "Faltan features requeridas "
            "por LightGBM:\n\n"
            + "\n".join(
                missing
            )
        )

