def build_row(
    self,
    data: Dict[
        str,
        Any
    ]
) -> pd.DataFrame:

    self.validate_features(
        data
    )

    row = {

        feature:
            data[
                feature
            ]

        for feature
        in self.features
    }

    df = pd.DataFrame(
        [
            row
        ]
    )

    return self.prepare_dataframe(
        df
    )

