def _obtener_id(
    documento: Optional[
        Dict[str, Any]
    ],
    *campos: str
) -> Optional[str]:

    if not documento:
        return None

    for campo in campos:

        valor = documento.get(
            campo
        )

        if valor is None:
            continue

        valor = str(
            valor
        ).strip()

        if valor:
            return valor

    return None


