# ============================================================

def _obtener_ids_productos(
    cls,
    productos: List[
        Dict[str, Any]
    ]
) -> List[str]:

    ids_productos = []

    for producto in productos:

        id_producto = (
            cls._obtener_id(
                producto,
                "id_producto",
                "id"
            )
        )

        if id_producto:

            ids_productos.append(
                id_producto
            )

    return list(
        dict.fromkeys(
            ids_productos
        )
    )


