def _normalizar_texto(
    valor: Any
) -> Optional[str]:

    if valor is None:
        return None

    valor = str(
        valor
    ).strip()

    if not valor:
        return None

    return valor


# ============================================================
# NORMALIZAR FECHA
# ============================================================

def _normalizar_fecha_base(
    fecha_base: Optional[
        date | datetime
    ] = None
) -> date:

    if fecha_base is None:

        return (
            datetime.now(
                timezone.utc
            )
            .date()
        )

    if isinstance(
        fecha_base,
        datetime
    ):

        return fecha_base.date()

    if isinstance(
        fecha_base,
        date
    ):

        return fecha_base

    raise TypeError(
        "fecha_base debe ser "
        "date, datetime o None."
    )


