def _validar_horizon(
    horizon: int
) -> int:

    try:

        horizon = int(
            horizon
        )

    except (
        TypeError,
        ValueError
    ):

        raise ValueError(
            "horizon debe ser un entero."
        )

    if horizon < 1 or horizon > 7:

        raise ValueError(
            "horizon debe estar "
            "entre 1 y 7."
        )

    return horizon


# ============================================================
# RANGO DE FECHAS
# ============================================================

def _crear_serie_diaria(
    cls,
    consumos: List[
        Dict[str, Any]
    ],
    fecha_base: date
) -> Dict[
    date,
    float
]:

    fecha_inicio = (

        fecha_base

        - timedelta(
            days=cls.MAX_LAG
        )
    )

    serie = {}

    fecha_actual = fecha_inicio

    while fecha_actual <= fecha_base:

        serie[
            fecha_actual
        ] = 0.0

        fecha_actual += timedelta(
            days=1
        )

    for registro in consumos:

        fecha = registro.get(
            "fecha"
        )

        cantidad = registro.get(
            "cantidad",
            0
        )

        if fecha is None:
            continue

        try:

            if isinstance(
                fecha,
                datetime
            ):

                fecha_registro = (
                    fecha.date()
                )

            elif isinstance(
                fecha,
                date
            ):

                fecha_registro = fecha

            else:

                fecha_registro = (
                    datetime.strptime(
                        str(fecha),
                        "%Y-%m-%d"
                    )
                    .date()
                )

        except (
            TypeError,
            ValueError
        ):

            continue

        if fecha_registro not in serie:
            continue

        try:

            cantidad_float = float(
                cantidad
            )

        except (
            TypeError,
            ValueError
        ):

            cantidad_float = 0.0

        serie[
            fecha_registro
        ] += cantidad_float

    return serie


# ============================================================
# LAG
# ============================================================

def _mean_anterior(
    serie: Dict[
        date,
        float
    ],
    fecha_base: date,
    window: int
) -> float:

    valores = []

    for lag in range(
        1,
        window + 1
    ):

        fecha_objetivo = (

            fecha_base

            - timedelta(
                days=lag
            )
        )

        valores.append(
            float(
                serie.get(
                    fecha_objetivo,
                    0.0
                )
            )
        )

    if not valores:
        return 0.0

    return float(
        sum(valores)
        / len(valores)
    )


