# ========================================================

def predict_batch(
    self,
    rows: Iterable[
        Dict[str, Any]
    ],
    horizon: int
) -> list[float]:

    if horizon < 1 or horizon > 7:

        raise ValueError(
            "El horizonte debe estar "
            "entre 1 y 7."
        )

    X = (
        self.feature_builder
        .build_dataframe(
            rows
        )
    )

    model = (
        self.loader
        .get_global_model(
            horizon
        )
    )

    predictions = (
        model.predict(
            X
        )
    )

    predictions = np.maximum(
        predictions,
        0
    )

    return [
        float(value)
        for value in predictions
    ]

