async def listar_por_estado(
    self,
    estado: str
) -> List[dict]:

    cursor = (
        self.collection()
        .find(
            {
                "estado":
                    estado
            },
            {
                "_id": 0
            }
        )
        .sort(
            "fecha_creacion",
            -1
        )
    )

    return await cursor.to_list(
        length=None
    )

