# ============================================================
# BUSCAR ALERTA ACTIVA
# ============================================================

async def buscar_activa(
    self,
    id_inventario: str,
    tipo_alerta: str
) -> Optional[dict]:

    return await self.collection().find_one(
        {
            "id_inventario":
                id_inventario,

            "tipo_alerta":
                tipo_alerta,

            "estado": {
                "$in": [
                    "ACTIVA",
                    "VISTA"
                ]
            }
        },
        {
            "_id": 0
        }
    )

# ============================================================
# ACTUALIZAR
# ============================================================

async def actualizar(
    self,
    id_alerta: str,
    datos: dict
) -> Optional[dict]:

    resultado = (
        await self.collection().update_one(
            {
                "id_alerta":
                    id_alerta
            },
            {
                "$set":
                    datos
            }
        )
    )

    if resultado.matched_count == 0:

        return None

    return await self.obtener_por_id(
        id_alerta
    )

