# ============================================================
# OBTENER SALIDAS DESDE UNA FECHA
#
# Utilizado por InventoryRiskService para calcular:
#
# - consumo reciente
# - demanda promedio
# - cobertura
# - riesgo de quiebre
# ============================================================

async def obtener_salidas_desde(
    self,
    id_inventario: str,
    fecha_desde: datetime
) -> List[dict]:

    cursor = (
        self.movimientos_collection()
        .find(
            {
                "id_inventario":
                    id_inventario,

                "tipo_movimiento":
                    "SALIDA",

                "fecha_hora": {
                    "$gte":
                        fecha_desde
                }
            },
            {
                "_id": 0
            }
        )
        .sort(
            "fecha_hora",
            1
        )
    )

    return await cursor.to_list(
        length=None
    )

async def crear(
    self,
    data: Dict[str, Any]
) -> Dict[str, Any]:

    documento = dict(data)

    documento[
        "id_movimiento"
    ] = str(
        uuid4()
    )

    # Si el servicio no envía fecha_hora,
    # utilizamos la fecha actual.
    if not documento.get(
        "fecha_hora"
    ):

        documento[
            "fecha_hora"
        ] = datetime.now(
            timezone.utc
        )

    await self.collection().insert_one(
        documento
    )

    return await self.obtener_por_id(
        documento[
            "id_movimiento"
        ]
    )


