# ============================================================
# SALIDAS DE PRODUCTO POR RANGO
# ============================================================

async def obtener_consumo_diario_inventario(
    self,
    id_inventario: str,
    fecha_inicio: datetime,
    fecha_fin: datetime
) -> List[Dict[str, Any]]:

    pipeline = [

        # ----------------------------------------------------
        # FILTRAR
        # ----------------------------------------------------

        {
            "$match": {

                "id_inventario":
                    id_inventario,

                "tipo_movimiento":
                    "SALIDA",

                "fecha_hora": {
                    "$gte":
                        fecha_inicio,

                    "$lte":
                        fecha_fin
                }
            }
        },

        # ----------------------------------------------------
        # AGRUPAR POR DIA
        # ----------------------------------------------------

        {
            "$group": {

                "_id": {
                    "$dateToString": {
                        "format":
                            "%Y-%m-%d",

                        "date":
                            "$fecha_hora",

                        "timezone":
                            "UTC"
                    }
                },

                "cantidad": {
                    "$sum":
                        "$cantidad"
                },

                "numero_movimientos": {
                    "$sum":
                        1
                }
            }
        },

        # ----------------------------------------------------
        # ORDENAR
        # ----------------------------------------------------

        {
            "$sort": {
                "_id":
                    1
            }
        },

        # ----------------------------------------------------
        # FORMATO DE SALIDA
        # ----------------------------------------------------

        {
            "$project": {

                "_id":
                    0,

                "fecha":
                    "$_id",

                "cantidad":
                    1,

                "numero_movimientos":
                    1
            }
        }
    ]

    cursor = self.collection().aggregate(
        pipeline
    )

    return await cursor.to_list(
        length=None
    )


# ============================================================
# CONSUMO AGREGADO POR DIA DE UN PRODUCTO
#
# NUEVO PARA ML
#
# A diferencia de:
#
# obtener_consumo_diario_inventario()
#
# aquí agrupamos todas las SALIDAS del mismo producto,
# independientemente del inventario/rack donde se encuentre.
#
# Esto nos permitirá construir:
#
# item_total_lag_1
# item_total_lag_7
# item_total_lag_28
#
# ============================================================

async def obtener_consumo_diario_productos(
    self,
    ids_productos: List[str],
    fecha_inicio: datetime,
    fecha_fin: datetime
) -> List[Dict[str, Any]]:

    # --------------------------------------------------------
    # VALIDAR LISTA
    # --------------------------------------------------------

    if not ids_productos:

        return []

    # Eliminar:
    #
    # None
    # strings vacíos
    # duplicados
    #
    # Manteniendo IDs como string.

    ids_limpios = list(
        dict.fromkeys(
            str(id_producto)
            for id_producto in ids_productos
            if id_producto
        )
    )

    if not ids_limpios:

        return []

    # --------------------------------------------------------
    # PIPELINE
    # --------------------------------------------------------

    pipeline = [

        # ----------------------------------------------------
        # FILTRAR PRODUCTOS + SALIDAS + FECHA
        # ----------------------------------------------------

        {
            "$match": {

                "id_producto": {
                    "$in":
                        ids_limpios
                },

                "tipo_movimiento":
                    "SALIDA",

                "fecha_hora": {
                    "$gte":
                        fecha_inicio,

                    "$lte":
                        fecha_fin
                }
            }
        },

        # ----------------------------------------------------
        # AGRUPAR TODOS LOS PRODUCTOS POR DIA
        # ----------------------------------------------------

        {
            "$group": {

                "_id": {
                    "$dateToString": {

                        "format":
                            "%Y-%m-%d",

                        "date":
                            "$fecha_hora",

                        "timezone":
                            "UTC"
                    }
                },

                "cantidad": {
                    "$sum":
                        "$cantidad"
                },

                "numero_movimientos": {
                    "$sum":
                        1
                },

                # Cantidad de productos diferentes
                # que tuvieron movimiento ese día.

                "productos_con_movimiento": {
                    "$addToSet":
                        "$id_producto"
                }
            }
        },

        # ----------------------------------------------------
        # ORDENAR
        # ----------------------------------------------------

        {
            "$sort": {

                "_id":
                    1
            }
        },

        # ----------------------------------------------------
        # FORMATO
        # ----------------------------------------------------

        {
            "$project": {

                "_id":
                    0,

                "fecha":
                    "$_id",

                "cantidad":
                    1,

                "numero_movimientos":
                    1,

                "numero_productos": {
                    "$size":
                        "$productos_con_movimiento"
                }
            }
        }
    ]

    cursor = (
        self.collection()
        .aggregate(
            pipeline
        )
    )

    return await cursor.to_list(
        length=None
    )

