async def actualizar(
    id_operario: str,
    data: Dict[str, Any]
) -> Optional[Dict[str, Any]]:

    data = dict(
        data
    )

    data[
        "fecha_actualizacion"
    ] = datetime.now(
        timezone.utc
    )

    result = await (
        OperarioRepository
        .collection()
        .update_one(
            {
                "id_operario":
                    id_operario
            },
            {
                "$set":
                    data
            }
        )
    )

    if result.matched_count == 0:
        return None

    return await (
        OperarioRepository
        .obtener_por_id(
            id_operario
        )
    )


