def _no_encontrado(
    detalle: str
) -> HTTPException:

    return HTTPException(
        status_code=(
            status.HTTP_404_NOT_FOUND
        ),
        detail=detalle
    )

def _prohibido(
    detalle: str = (
        "No tiene acceso a este recurso"
    )
) -> HTTPException:

    return HTTPException(
        status_code=(
            status.HTTP_403_FORBIDDEN
        ),
        detail=detalle
    )

