    ]

def filtrar_empresa(
    user: UsuarioActual,
    items: Iterable[Dict[str, Any]]
) -> List[Dict[str, Any]]:

    return [
        item
        for item in items
        if item.get("id_empresa")
        == user.id_empresa
    ]


