def verificar_empresa(
    user: UsuarioActual,
    id_empresa: str
) -> None:

    if id_empresa != user.id_empresa:

        raise _no_encontrado(
            "Empresa no encontrada"
        )


# ============================================================
# ALMACEN
# ============================================================

async def verificar_almacen(
    user: UsuarioActual,
    id_almacen: str
) -> Dict[str, Any]:

    if user.es_proveedor:

        raise _prohibido()

    almacen = await (
        AlmacenRepository.obtener_por_id(
            id_almacen
        )
    )

    if (
        not almacen
        or
        almacen.get("id_empresa")
        != user.id_empresa
    ):

        raise _no_encontrado(
            "Almacén no encontrado"
        )

    if (
        user.es_operario
        and
        id_de_almacen(almacen)
        != user.id_almacen
    ):

        raise _prohibido(
            "No tiene acceso a este almacén"
        )

    return almacen


# ============================================================
# ZONA
# ============================================================

async def verificar_zona(
    user: UsuarioActual,
    id_zona: str
) -> Dict[str, Any]:

    if user.es_proveedor:

        raise _prohibido()

    zona = await (
        ZonaRepository.obtener_por_id(
            id_zona
        )
    )

    if not zona:

        raise _no_encontrado(
            "Zona no encontrada"
        )

    almacen = await (
        AlmacenRepository.obtener_por_id(
            zona.get("id_almacen")
        )
    )

    if (
        not almacen
        or
        almacen.get("id_empresa")
        != user.id_empresa
    ):

        raise _no_encontrado(
            "Zona no encontrada"
        )

    if (
        user.es_operario
        and
        zona.get("id_almacen")
        != user.id_almacen
    ):

        raise _prohibido(
            "No tiene acceso a esta zona"
        )

    return zona


# ============================================================
# RACK
# ============================================================

async def verificar_rack(
    user: UsuarioActual,
    id_rack: str
) -> Dict[str, Any]:

    rack = await (
        RackRepository.obtener_por_id(
            id_rack
        )
    )

    if not rack:

        raise _no_encontrado(
            "Rack no encontrado"
        )

    try:

        await AccesoService.verificar_zona(
            user,
            rack.get("id_zona")
        )

    except HTTPException as exc:

        if exc.status_code == 404:

            raise _no_encontrado(
                "Rack no encontrado"
            )

        raise _prohibido(
            "No tiene acceso a este rack"
        )

    return rack


