async def verificar_recepcion(
    user: UsuarioActual,
    id_recepcion: str
) -> Dict[str, Any]:

    recepcion = await (
        RecepcionMercaderiaRepository()
        .obtener_por_id(
            id_recepcion
        )
    )

    if not recepcion:

        raise _no_encontrado(
            "Recepción no encontrada"
        )

    orden = await (
        OrdenReposicionRepository()
        .obtener_por_id(
            recepcion.get(
                "id_orden_reposicion"
            )
        )
    )

    if (
        not orden
        or
        orden.get("id_empresa")
        != user.id_empresa
    ):

        raise _no_encontrado(
            "Recepción no encontrada"
        )

    if (
        user.es_proveedor
        or
        (
            user.es_operario
            and
            orden.get("id_almacen")
            != user.id_almacen
        )
    ):

        raise _prohibido(
            "No tiene acceso a esta recepción"
        )

    return recepcion

