def convertir_decimal(
    data: Dict[str, Any]
) -> Dict[str, Any]:

    data = dict(
        data
    )

    for campo in [
        "latitud",
        "longitud"
    ]:

        if (
            campo in data
            and
            isinstance(
                data[campo],
                Decimal
            )
        ):

            data[campo] = float(
                data[campo]
            )

    return data


