async def login_empresa(
    data: EmpresaLoginRequest
) -> Dict[str, Any]:

    correo = (
        str(data.correo)
        .lower()
        .strip()
    )

    empresa = (
        await empresa_repository
        .find_by_email(
            correo
        )
    )

    if not empresa:

        raise HTTPException(
            status_code=(
                status.HTTP_401_UNAUTHORIZED
            ),
            detail=(
                "Correo o contraseña incorrectos"
            )
        )

    stored_password = (
        empresa.get(
            "password"
        )
    )

    if (
        not stored_password
        or
        not verify_password(
            data.password,
            stored_password
        )
    ):

        raise HTTPException(
            status_code=(
                status.HTTP_401_UNAUTHORIZED
            ),
            detail=(
                "Correo o contraseña incorrectos"
            )
        )

    token = create_access_token(
        empresa[
            "id_empresa"
        ]
    )

    return {

        "access_token":
            token,

        "token_type":
            "bearer",

        "empresa":
            sanitize_empresa(
                empresa
            )
    }


