async def update_empresa_profile(
    id_empresa: str,
    data: EmpresaUpdateRequest
) -> Dict[str, Any]:

    current = (
        await empresa_repository
        .find_by_id(
            id_empresa
        )
    )

    if not current:

        raise HTTPException(
            status_code=(
                status.HTTP_404_NOT_FOUND
            ),
            detail=(
                "Empresa no encontrada"
            )
        )

    update_data = (
        data.model_dump(
            exclude_unset=True
        )
    )

    if not update_data:

        return sanitize_empresa(
            current
        )

    # ========================================================
    # CORREO
    # ========================================================

    if "correo" in update_data:

        correo = (
            str(
                update_data[
                    "correo"
                ]
            )
            .lower()
            .strip()
        )

        existing = (
            await empresa_repository
            .find_by_email(
                correo
            )
        )

        if (
            existing
            and
            existing[
                "id_empresa"
            ]
            !=
            id_empresa
        ):

            raise HTTPException(
                status_code=(
                    status.HTTP_409_CONFLICT
                ),
                detail=(
                    "El correo ya está registrado"
                )
            )

        await validar_correo_disponible(
            correo,
            id_empresa
        )

        if current.get("correo") and current.get("correo").lower() != correo:
            update_data["correo_verificado"] = False
            update_data["fecha_verificacion_correo"] = None

        update_data[
            "correo"
        ] = correo


    # ========================================================
    # RUC
    # ========================================================

    if "ruc" in update_data:

        ruc = (
            update_data[
                "ruc"
            ]
            .strip()
        )

        existing = (
            await empresa_repository
            .find_by_ruc(
                ruc
            )
        )

        if (
            existing
            and
            existing[
                "id_empresa"
            ]
            !=
            id_empresa
        ):

            raise HTTPException(
                status_code=(
                    status.HTTP_409_CONFLICT
                ),
                detail=(
                    "El RUC ya está registrado"
                )
            )

        update_data[
            "ruc"
        ] = ruc


    # ========================================================
    # NORMALIZAR TEXTOS
    # ========================================================

    for field in [
        "nombre",
        "sector",
        "telefono"
    ]:

        if (
            field in update_data
            and
            update_data[field]
        ):

            update_data[
                field
            ] = (
                update_data[
                    field
                ]
                .strip()
            )


    updated = (
        await empresa_repository
        .update_empresa(
            id_empresa,
            update_data
        )
    )

    if not updated:

        raise HTTPException(
            status_code=(
                status.HTTP_404_NOT_FOUND
            ),
            detail=(
                "Empresa no encontrada"
            )
        )

    return sanitize_empresa(
        updated
    )


