async def change_empresa_password(
    id_empresa: str,
    data: EmpresaChangePasswordRequest
) -> Dict[str, str]:

    empresa = (
        await empresa_repository
        .find_by_id(
            id_empresa
        )
    )

    if not empresa:

        raise HTTPException(
            status_code=(
                status.HTTP_404_NOT_FOUND
            ),
            detail=(
                "Empresa no encontrada"
            )
        )

    current_hash = (
        empresa.get(
            "password"
        )
    )

    if (
        not current_hash
        or
        not verify_password(
            data.password_actual,
            current_hash
        )
    ):

        raise HTTPException(
            status_code=(
                status.HTTP_400_BAD_REQUEST
            ),
            detail=(
                "La contraseña actual "
                "es incorrecta"
            )
        )

    if (
        data.password_actual
        ==
        data.password_nueva
    ):

        raise HTTPException(
            status_code=(
                status.HTTP_400_BAD_REQUEST
            ),
            detail=(
                "La nueva contraseña debe "
                "ser diferente a la actual"
            )
        )

    new_hash = hash_password(
        data.password_nueva
    )

    success = (
        await empresa_repository
        .update_password(
            id_empresa,
            new_hash
        )
    )

    if not success:

        raise HTTPException(
            status_code=(
                status.HTTP_500_INTERNAL_SERVER_ERROR
            ),
            detail=(
                "No se pudo actualizar "
                "la contraseña"
            )
        )

    return {
        "mensaje":
            "Contraseña actualizada correctamente"
    }


