def _safe_float(
    value,
    default: float = 0.0
) -> float:

    try:

        valor = float(value)

        if math.isnan(valor):
            return default

        if math.isinf(valor):
            return default

        return valor

    except (
        TypeError,
        ValueError
    ):

        return default

# ========================================================
# PROMEDIO
# ========================================================

def _calcular_tendencia(
    promedio_7d: float,
    promedio_28d: float
) -> float:

    if promedio_28d <= 0:

        if promedio_7d > 0:
            return 100.0

        return 0.0

    return (
        (
            promedio_7d
            - promedio_28d
        )
        / promedio_28d
    ) * 100

# ========================================================
# CONSUMO DIARIO DE LOS ULTIMOS 28 DIAS
# ========================================================

def _consumo_diario_28d(
    movimientos: list,
    ahora: datetime
) -> list[float]:

    consumos = [
        0.0
        for _ in range(28)
    ]

    fecha_inicio = (
        ahora.date()
        - timedelta(
            days=27
        )
    )

    for movimiento in movimientos:

        fecha = movimiento.get(
            "fecha_hora"
        )

        if not isinstance(
            fecha,
            datetime
        ):
            continue

        fecha_movimiento = (
            fecha.date()
        )

        indice = (
            fecha_movimiento
            - fecha_inicio
        ).days

        if (
            0
            <= indice
            < 28
        ):

            cantidad = float(
                movimiento.get(
                    "cantidad",
                    0
                )
            )

            consumos[
                indice
            ] += cantidad

    return consumos

# ========================================================
# NORMALIZAR FECHA
# ========================================================

def _normalizar_datetime(
    value
) -> datetime:

    fecha = pd.to_datetime(
        value
    )

    if isinstance(
        fecha,
        pd.Timestamp
    ):

        fecha = (
            fecha.to_pydatetime()
        )

    if fecha.tzinfo is None:

        fecha = fecha.replace(
            tzinfo=timezone.utc
        )

    return fecha

# ========================================================
# GENERAR FORECAST LIGHTGBM
# ========================================================

def _calcular_fecha_quiebre(
    stock_actual: float,
    forecast: ForecastInfo,
    fecha_base: datetime
) -> datetime | None:

    # Ya no existe stock.
    if stock_actual <= 0:

        return fecha_base

    acumulado = 0.0

    for prediccion in (
        forecast.predicciones_diarias
    ):

        acumulado += (
            prediccion.demanda_predicha
        )

        if acumulado >= stock_actual:

            return (
                prediccion.fecha
            )

    # El forecast solamente cubre 7 días.
    #
    # Si no se agota dentro de esos 7 días,
    # no inventamos una fecha posterior.
    return None

# ========================================================
# NIVEL DE RIESGO
# ========================================================

def _calcular_nivel_riesgo(
    stock_actual: float,
    dias_cobertura: float | None,
    lead_time_dias: int,
    punto_reposicion: float
) -> NivelRiesgo:

    if stock_actual <= 0:

        return (
            NivelRiesgo.CRITICO
        )

    if dias_cobertura is None:

        return (
            NivelRiesgo.BAJO
        )

    if (
        lead_time_dias > 0
        and
        dias_cobertura
        <= lead_time_dias
    ):

        return (
            NivelRiesgo.CRITICO
        )

    if (
        punto_reposicion > 0
        and
        stock_actual
        <= punto_reposicion
    ):

        return (
            NivelRiesgo.ALTO
        )

    if (
        lead_time_dias > 0
        and
        dias_cobertura
        <= lead_time_dias * 1.5
    ):

        return (
            NivelRiesgo.MEDIO
        )

    return NivelRiesgo.BAJO

# ========================================================
# SCORE DE RIESGO
# ========================================================

def _calcular_score(
    stock_actual: float,
    dias_cobertura: float | None,
    lead_time_dias: int,
    punto_reposicion: float
) -> float:

    if stock_actual <= 0:
        return 100.0

    score = 0.0

    if (
        dias_cobertura is not None
        and
        lead_time_dias > 0
    ):

        ratio_cobertura = (
            dias_cobertura
            / lead_time_dias
        )

        if ratio_cobertura <= 1:
            score += 60

        elif ratio_cobertura <= 1.5:
            score += 40

        elif ratio_cobertura <= 2:
            score += 20

    if punto_reposicion > 0:

        ratio_stock = (
            stock_actual
            / punto_reposicion
        )

        if ratio_stock <= 0.5:
            score += 40

        elif ratio_stock <= 1:
            score += 30

        elif ratio_stock <= 1.25:
            score += 15

    return round(
        min(
            score,
            100
        ),
        2
    )

