# CALCULO DE REPOSICION
# ========================================================

async def evaluar_todos(
    self,
    generar_alertas: bool = False,
    ids_inventario: set | None = None
) -> list[
    InventoryRiskResponse
]:

    inventarios = (
        await self.repository
        .listar_inventarios()
    )

    resultados = []

    for inventario in inventarios:

        id_inventario = (
            inventario.get(
                "id_inventario"
            )
            or inventario.get(
                "id"
            )
        )

        if not id_inventario:
            continue

        # Alcance de la empresa (None = todos)
        if (
            ids_inventario is not None
            and id_inventario not in ids_inventario
        ):
            continue

        resultado = (
            await self.evaluar(

                id_inventario=
                    id_inventario,

                generar_alertas=
                    generar_alertas
            )
        )

        resultados.append(
            resultado
        )

    return resultados

def validar_tipo_motivo(
    self,
    tipo: TipoMovimiento,
    motivo: MotivoMovimiento
):

    motivos_entrada = {
        MotivoMovimiento.RECEPCION,
        MotivoMovimiento.REPOSICION,
        MotivoMovimiento.DEVOLUCION,
        MotivoMovimiento.CONTEO_FISICO,
        MotivoMovimiento.OTRO
    }

    motivos_salida = {
        MotivoMovimiento.VENTA,
        MotivoMovimiento.MERMA,
        MotivoMovimiento.VENCIMIENTO,
        MotivoMovimiento.CONTEO_FISICO,
        MotivoMovimiento.OTRO
    }

    motivos_ajuste = {
        MotivoMovimiento.CONTEO_FISICO,
        MotivoMovimiento.OTRO
    }

    if (
        tipo == TipoMovimiento.ENTRADA
        and motivo not in motivos_entrada
    ):
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail=(
                f"El motivo {motivo.value} "
                "no es válido para una ENTRADA"
            )
        )

    if (
        tipo == TipoMovimiento.SALIDA
        and motivo not in motivos_salida
    ):
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail=(
                f"El motivo {motivo.value} "
                "no es válido para una SALIDA"
            )
        )

    if (
        tipo == TipoMovimiento.AJUSTE
        and motivo not in motivos_ajuste
    ):
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail=(
                f"El motivo {motivo.value} "
                "no es válido para un AJUSTE"
            )
        )

