async def actualizar_operario(
    self,
    id_operario: str,
    data: OperarioUpdate,
    user: UsuarioActual
):

    operario = await self.obtener_operario(
        id_operario,
        user
    )

    update_data = (
        data.model_dump(
            exclude_unset=True
        )
    )

    update_data = {
        campo: valor
        for campo, valor in update_data.items()
        if valor is not None
    }

    if not update_data:
        return operario


    if "id_almacen" in update_data:

        await self.validar_almacen(
            user.id_empresa,
            update_data["id_almacen"]
        )


    if "correo" in update_data:

        update_data[
            "correo"
        ] = await (
            self.validar_correo_disponible(
                str(update_data["correo"]),
                id_operario
            )
        )

        # Correo distinto -> hay que verificarlo de nuevo
        if (
            (operario.get("correo") or "").lower()
            != update_data["correo"]
        ):
            update_data["correo_verificado"] = False
            update_data["fecha_verificacion_correo"] = None


    for campo in [
        "nombre",
        "apellido",
        "cargo"
    ]:

        if campo in update_data:

            update_data[
                campo
            ] = (
                update_data[
                    campo
                ].strip()
            )


    for campo in [
        "turno",
        "estado"
    ]:

        if campo in update_data:

            update_data[
                campo
            ] = (
                update_data[
                    campo
                ]
                .strip()
                .upper()
            )


    actualizado = await (
        OperarioRepository
        .actualizar(
            id_operario,
            update_data
        )
    )

    if not actualizado:

        raise HTTPException(
            status_code=
                status.HTTP_404_NOT_FOUND,
            detail=
                "Operario no encontrado"
        )

    return self.sanitizar(
        actualizado
    )


