async def crear(
    data: ProductoCreate
):

    # --------------------------------------------------------
    # VALIDAR EMPRESA
    # --------------------------------------------------------

    empresa = await (
        EmpresaRepository.obtener_por_id(
            data.id_empresa
        )
    )

    if not empresa:

        raise HTTPException(
            status_code=(
                status.HTTP_404_NOT_FOUND
            ),
            detail="Empresa no encontrada"
        )


    # --------------------------------------------------------
    # VALIDAR RACK
    # --------------------------------------------------------

    # El rack de referencia es opcional al crear.
    rack = (
        await RackRepository.obtener_por_id(
            data.id_rack
        )
        if data.id_rack
        else None
    )

    if data.id_rack and not rack:

        raise HTTPException(
            status_code=(
                status.HTTP_404_NOT_FOUND
            ),
            detail="Rack no encontrado"
        )


    # --------------------------------------------------------
    # VALIDAR REFRIGERACION
    # --------------------------------------------------------

    if data.requiere_refrigeracion:

        if (
            data.temperatura_min_almacenamiento
            is None
            or
            data.temperatura_max_almacenamiento
            is None
        ):

            raise HTTPException(
                status_code=(
                    status.HTTP_400_BAD_REQUEST
                ),
                detail=(
                    "Si el producto requiere refrigeración, "
                    "debe indicar temperatura mínima y máxima"
                )
            )

        if (
            data.temperatura_min_almacenamiento
            >
            data.temperatura_max_almacenamiento
        ):

            raise HTTPException(
                status_code=(
                    status.HTTP_400_BAD_REQUEST
                ),
                detail=(
                    "La temperatura mínima no puede ser "
                    "mayor que la temperatura máxima"
                )
            )


    # --------------------------------------------------------
    # CONSTRUIR PRODUCTO
    # --------------------------------------------------------

    producto = (
        data.model_dump()
    )

    producto.pop("stock", None)


    # --------------------------------------------------------
    # LIMPIAR TEXTOS
    # --------------------------------------------------------

    producto["nombre"] = (
        producto[
            "nombre"
        ].strip()
    )

    producto["categoria"] = (
        producto[
            "categoria"
        ].strip()
    )

    producto["familia"] = (
        producto[
            "familia"
        ].strip()
    )

    if producto.get("marca"):

        producto["marca"] = (
            producto[
                "marca"
            ].strip()
        )


    # --------------------------------------------------------
    # ID Y FECHAS
    # --------------------------------------------------------

    producto[
        "id_producto"
    ] = str(
        uuid4()
    )


    now = datetime.now(
        timezone.utc
    )


    producto[
        "fecha_creacion"
    ] = now

    producto[
        "fecha_actualizacion"
    ] = now


    # --------------------------------------------------------
    # GUARDAR
    # --------------------------------------------------------

    return await (
        ProductoRepository.crear(
            producto
        )
    )


