# ============================================================
# OBTENER REFRIGERADOS
# ============================================================

async def actualizar(
    id_producto: str,
    data: ProductoUpdate
):

    producto_actual = await (
        ProductoRepository
        .obtener_por_id(
            id_producto
        )
    )

    if not producto_actual:

        raise HTTPException(
            status_code=(
                status.HTTP_404_NOT_FOUND
            ),
            detail="Producto no encontrado"
        )


    update_data = (
        data.model_dump(
            exclude_unset=True
        )
    )

    update_data.pop("stock", None)


    # --------------------------------------------------------
    # VALIDAR NUEVO RACK
    # --------------------------------------------------------

    if (
        "id_rack" in update_data
        and
        update_data[
            "id_rack"
        ] is not None
    ):

        rack = await (
            RackRepository.obtener_por_id(
                update_data[
                    "id_rack"
                ]
            )
        )

        if not rack:

            raise HTTPException(
                status_code=(
                    status.HTTP_404_NOT_FOUND
                ),
                detail="Rack no encontrado"
            )


    # --------------------------------------------------------
    # REFRIGERACION RESULTANTE
    # --------------------------------------------------------

    requiere = (
        update_data.get(
            "requiere_refrigeracion",
            producto_actual.get(
                "requiere_refrigeracion",
                False
            )
        )
    )


    temperatura_min = (
        update_data.get(
            "temperatura_min_almacenamiento",
            producto_actual.get(
                "temperatura_min_almacenamiento"
            )
        )
    )


    temperatura_max = (
        update_data.get(
            "temperatura_max_almacenamiento",
            producto_actual.get(
                "temperatura_max_almacenamiento"
            )
        )
    )


    if requiere:

        if (
            temperatura_min is None
            or
            temperatura_max is None
        ):

            raise HTTPException(
                status_code=(
                    status.HTTP_400_BAD_REQUEST
                ),
                detail=(
                    "Un producto refrigerado debe tener "
                    "temperatura mínima y máxima"
                )
            )


        if (
            temperatura_min
            >
            temperatura_max
        ):

            raise HTTPException(
                status_code=(
                    status.HTTP_400_BAD_REQUEST
                ),
                detail=(
                    "La temperatura mínima no puede ser "
                    "mayor que la temperatura máxima"
                )
            )


    # --------------------------------------------------------
    # SI YA NO REQUIERE REFRIGERACION
    # --------------------------------------------------------

    if (
        update_data.get(
            "requiere_refrigeracion"
        )
        is False
    ):

        update_data[
            "temperatura_min_almacenamiento"
        ] = None

        update_data[
            "temperatura_max_almacenamiento"
        ] = None


    # --------------------------------------------------------
    # LIMPIAR TEXTOS
    # --------------------------------------------------------

    for campo in [
        "nombre",
        "categoria",
        "familia",
        "marca"
    ]:

        if (
            campo in update_data
            and
            isinstance(
                update_data[
                    campo
                ],
                str
            )
        ):

            update_data[
                campo
            ] = (
                update_data[
                    campo
                ].strip()
            )


    if not update_data:

        return producto_actual


    producto_actualizado = await (
        ProductoRepository.actualizar(
            id_producto,
            update_data
        )
    )


    if not producto_actualizado:

        raise HTTPException(
            status_code=(
                status.HTTP_404_NOT_FOUND
            ),
            detail="Producto no encontrado"
        )


    return producto_actualizado


