def classify(cls, message: str, history: list[dict] | None = None) -> SaikiIntent:
    text = cls._normalize(message)
    if re.fullmatch(r'\s*(hola|buenos dias|buenas tardes|buenas noches|hey)(\s+saiki)?[!,.?\s]*', text):
        return SaikiIntent('greeting', frozenset())
    horizon = cls._horizon_days(text)
    analysis = bool(re.search(r'analiz|evalua|prioriz|justific|por que|motivo|explica', text))
    replenishment = bool(re.search(r'repon|reposicion|comprar|recomend', text))
    if analysis and replenishment:
        return SaikiIntent('analysis', cls.MIXED_TOOLS, horizon)
    listing = bool(re.search(r'mencion|enumera|lista|listado|detalle|desglos|muestra|dime|dame|ensena|quiero ver|que productos', text))
    inventory = bool(re.search(r'producto|inventario|existencia|stock', text))
    location = bool(re.search(r'ubicacion|rack|zona|donde', text))
    quantities = bool(re.search(r'cantidad|stock|unidades|existencia', text))
    other_operation = bool(re.search(r'alert|movimiento|entrada|salida|riesgo|agot|demanda|predic|repon|recomend', text))
    if listing and inventory and not other_operation:
        if location:
            return SaikiIntent('inventory_detail', frozenset({'get_warehouse_status'}))
        if quantities or re.search(r'mencion|enumera|listado|lista\b|todos.*productos', text):
            return SaikiIntent('product_quantities', frozenset({'get_warehouse_status', 'get_product'}))
    predictive = bool(re.search(r'proyect|proyecc|pronostic|predec|predic|demanda futura|agot|quedarse sin|alcanzara|necesitare', text)) or (bool(re.search(r'demanda|vendera|venderan', text)) and horizon is not None)
    if predictive or (horizon is not None and cls._history_has_predictive_request(history)):
        return SaikiIntent('predictive', cls.PREDICTIVE_TOOLS, horizon if horizon is not None else 7)
    qualified = bool(re.search(r'\brack|\bzona|\bcon\b|\bsin\b|\b(?:de|en|para|del)\b', text))
    if not qualified and re.search(r'\bcuantos? productos\b', text) and re.search(r'\btengo\b', text):
        return SaikiIntent('product_count', frozenset({'get_product'}))
    if not qualified and re.search(r'\b(?:tengo|hay|existen) almacenes\b', text):
        return SaikiIntent('warehouses', frozenset({'get_warehouse_status'}))
    if not qualified and re.search(r'\bcuanto (?:stock|inventario)\b', text) and re.search(r'\btengo\b', text):
        return SaikiIntent('stock_total', frozenset({'get_warehouse_status'}))
    categories = [
        ('movements', r'movimiento|entrada|salida|venta|historial', {'get_recent_movements'}),
        ('alerts', r'alerta|aviso', {'get_active_alerts'}),
        ('recommendations', r'recomend|reponer|reposicion|comprar', {'get_recommendations'}),
        ('risk', r'riesgo|desabastec', {'get_inventory_risk', 'get_forecast', 'get_warehouse_status'}),
        ('location', r'donde|ubicacion|localiza|en que rack|en que zona', {'get_warehouse_status', 'get_product'}),
        ('stock', r'stock|existencia|cuantas unidades|cantidad disponible', {'get_warehouse_status', 'get_inventory', 'get_product'}),
        ('products', r'producto|catalogo', {'get_product', 'get_warehouse_status'}),
    ]
    matches = [(kind, tools) for kind, pattern, tools in categories if re.search(r'\b(?:' + pattern + ')', text)]
    if matches:
        tools = frozenset().union(*(tools for _, tools in matches))
        return SaikiIntent(matches[0][0] if len(matches) == 1 else 'mixed', tools)
    if re.search(r'\bmuestrame\s+(?:el|la)\b', text):
        return SaikiIntent('products', frozenset({'get_product', 'get_warehouse_status'}))
    if re.search(r'inventario|almacen', text) and re.search(r'como|estado|resumen|situacion|panorama', text):
        return SaikiIntent('general', frozenset({'get_warehouse_status'}))
    return SaikiIntent('ambiguous', frozenset())

def _horizon_days(text):
    text = re.sub(r'\btreinta\b', '30', text)
    text = re.sub(r'\bsiete\b', '7', text)
    match = re.search(r'\b(\d+)\s*(dias?|semanas?|mes(?:es)?)\b', text)
    if match:
        return int(match[1]) * (7 if 'semana' in match[2] else 30 if 'mes' in match[2] else 1)
    if re.search(r'\b(?:una|la proxima|esta) semana\b', text):
        return 7
    if re.search(r'\b(?:un|el proximo|este) mes\b', text):
        return 30
    return None

async def inventory_summary(user, page=1, page_size=25):
    if user is None:
        raise HTTPException(401, "Se requiere autenticación para consultar el inventario.")
    if user.es_proveedor:
        raise HTTPException(403, "No tiene acceso al inventario.")
    warehouses = await AlmacenRepository.obtener_por_empresa(user.id_empresa)
    if user.es_operario:
        warehouses = [row for row in warehouses if identifier(row, "id_almacen") == user.id_almacen]
    warehouse_map = {identifier(row, "id_almacen"): row for row in warehouses}
    zones = await ZonaRepository.obtener_por_almacenes(list(warehouse_map)) if warehouse_map else []
    zone_map = {identifier(row, "id_zona"): row for row in zones}
    racks = await RackRepository.obtener_por_zonas(list(zone_map)) if zone_map else []
    rack_map = {identifier(row, "id_rack"): row for row in racks}
    inventories = await InventarioRepository().obtener_por_racks(list(rack_map)) if rack_map else []
    products = await ProductoRepository.collection().find({"id_empresa": user.id_empresa}, {"_id": 0}).to_list(length=None)
    product_map = {row["id_producto"]: row for row in products}
    # A corrupted cross-company product reference must never expose its stock.
    inventories = [row for row in inventories if row.get("id_producto") in product_map]
    grouped = {}
    for item in inventories:
        stock = item.get("stock_actual")
        if not numeric(stock) or stock < 0:
            raise HTTPException(503, "No se pudo verificar el stock: existen cantidades inválidas.")
        key = (item["id_producto"], item["id_rack"])
        group = grouped.setdefault(key, {"stock": 0, "ids": [], "minimums": []})
        group["stock"] += stock
        group["ids"].append(item["id_inventario"])
        group["minimums"].append(item.get("stock_minimo"))
    rows = []
    for (product_id, rack_id), group in grouped.items():
        rack = rack_map[rack_id]
        zone = zone_map[rack["id_zona"]]
        warehouse = warehouse_map[zone["id_almacen"]]
        stock = group["stock"]
        minimum = group["minimums"][0] if len(group["minimums"]) == 1 else None
        status = "Sin stock" if stock == 0 else "Sin determinar"
        if stock > 0 and numeric(minimum) and minimum >= 0:
            status = "Bajo stock" if stock <= minimum else "Disponible"
        rows.append({"id_producto": product_id, "product_name": product_map[product_id].get("nombre"),
                     "id_almacen": identifier(warehouse, "id_almacen"), "warehouse_name": warehouse.get("nombre"),
                     "id_zona": identifier(zone, "id_zona"), "zone_name": zone.get("nombre"),
                     "id_rack": rack_id, "rack_name": rack.get("codigo") or rack.get("nombre"),
                     "inventory_ids": sorted(group["ids"]), "stock": stock, "status_label": status})
    rows.sort(key=lambda row: (row["id_producto"], row["id_almacen"], row["id_zona"], row["id_rack"]))
    total_units = sum(row["stock"] for row in rows)
    positive_products = {row["id_producto"] for row in rows if row["stock"] > 0}
    state = ("sin_almacenes" if not warehouses else "almacen_sin_productos" if not products and not inventories
             else "productos_sin_inventario" if not inventories else "stock_cero" if total_units == 0 else "stock_positivo")
    summary = {"distinct_products": len(positive_products), "total_units": total_units,
               "warehouse_count": len(warehouses), "catalog_products": len(products), "inventory_state": state,
               "rows": rows[(page - 1) * page_size:page * page_size],
               "pagination": {"page": page, "page_size": page_size, "total_rows": len(rows),
                              "total_pages": math.ceil(len(rows) / page_size)}}
    visualization = {"type": "inventory_summary", "version": 1, "title": "Resumen de inventario",
                     "cards": [{"label": label, "value_path": "data.inventory_summary." + key}
                               for label, key in (("Productos", "distinct_products"), ("Unidades", "total_units"), ("Almacenes", "warehouse_count"))],
                     "table": {"rows_path": "data.inventory_summary.rows",
                               "columns": [{"key": key, "label": label} for key, label in
                                           (("product_name", "Producto"), ("stock", "Stock"), ("warehouse_name", "Almacén"),
                                            ("zone_name", "Zona"), ("rack_name", "Rack"), ("status_label", "Estado"))],
                               "pagination_path": "data.inventory_summary.pagination"}}
    stock_by_product = {}
    for row in rows:
        stock_by_product[row["id_producto"]] = stock_by_product.get(row["id_producto"], 0) + row["stock"]
    return {"inventory_summary": summary, "visualization": visualization,
            "estado_inventario": state, "total_almacenes": len(warehouses),
            "total_registros_inventario": len(inventories), "productos_distintos": len(stock_by_product),
            "stock_total_unidades": total_units, "almacenes": warehouses, "inventarios": inventories[:50],
            "stock_por_producto": [{"id_producto": key, "nombre": product_map[key].get("nombre"), "stock_actual": value}
                                   for key, value in stock_by_product.items()],
            "ubicaciones": [{"id_producto": row["id_producto"], "id_rack": row["id_rack"], "stock_actual": row["stock"],
                             "rack": rack_map[row["id_rack"]], "zona": zone_map[row["id_zona"]]} for row in rows]}

def number(value):
    if value is None or not isinstance(value, (int, float)) or not math.isfinite(value):
        return None
    return f"{value:g}"

def operational_answer(kind, rows):
    count = len(rows)
    if kind == "alerts":
        level = str(rows[0].get("nivel_riesgo", "")).lower() if count == 1 else ""
        detail = f" de riesgo {level}" if level in {"bajo", "medio", "alto", "critico"} else ""
        return "No tienes alertas activas." if not count else f"Tienes {count} alerta{'s' if count != 1 else ''} activa{'s' if count != 1 else ''}{detail}. Puedes consultar los detalles en los datos adjuntos."
    if kind == "movements":
        if not count:
            return "No encontré movimientos recientes."
        quantity = number(rows[0].get("cantidad"))
        movement = rows[0].get("tipo_movimiento")
        if count == 1 and quantity is not None and movement in {"SALIDA", "ENTRADA"}:
            return f"Encontré un movimiento reciente: una {movement.lower()} de {quantity} {'unidad' if quantity == '1' else 'unidades'}."
        return f"Encontré {count} movimiento{'s' if count != 1 else ''} reciente{'s' if count != 1 else ''}. Los detalles están disponibles en la respuesta."
    if kind == "recommendations":
        pending = [row for row in rows if row.get("estado") in {"PENDIENTE", "VALIDADA_OPERARIO", "CAMBIOS_SOLICITADOS", "APROBADA_EMPRESA", "ACEPTADA"}]
        if not pending:
            return "No hay recomendaciones pendientes de reposición registradas."
        if len(pending) == 1 and number(pending[0].get("cantidad_recomendada")) is not None:
            return f"La recomendación registrada propone reponer {number(pending[0]['cantidad_recomendada'])} unidades. Revisa el producto y los detalles antes de iniciar una compra."
        return f"Tienes {len(pending)} {'recomendación pendiente' if len(pending) == 1 else 'recomendaciones pendientes'}. Revisa las cantidades propuestas antes de iniciar una compra."
    raise ValueError("Unsupported operational answer")

async def health(self) -> dict:
    base = {
        "ollama_base_url": self.settings.ollama_base_url,
        "model": self.settings.ollama_model,
    }
    try:
        models = await asyncio.to_thread(self._installed_models)
    except RuntimeError as exc:
        return {"status": "unavailable", "ready": False, **base, "detail": str(exc)}
    if self.settings.ollama_model not in models:
        return {
            "status": "unavailable",
            "ready": False,
            **base,
            "detail": f"El modelo {self.settings.ollama_model} no está descargado en Ollama.",
        }
    return {"status": "ok", "ready": True, **base}

def _installed_models(self) -> list[str]:
    url = f"{self.settings.ollama_base_url.rstrip('/')}/api/tags"
    try:
        with request.urlopen(url, timeout=5) as response:
            data = json.loads(response.read().decode("utf-8"))
    except (error.URLError, TimeoutError, json.JSONDecodeError) as exc:
        raise RuntimeError(f"No se pudo conectar con Ollama en {url}: {exc}") from exc
    return [model.get("name", "") for model in data.get("models", [])]

async def _ask(
    self,
    data: SaikiAskRequest,
    user: UsuarioActual | None = None,
    intent=None,
) -> dict:
    context = dict(data.context)
    intent = intent or self.intent_router.classify(data.message or "", data.history)
    if intent.kind == "greeting":
        return self._simple_response(
            "¡Hola, soy Saiki!",
            source="router",
        )
    if intent.horizon_days is not None and intent.horizon_days not in self.intent_router.SUPPORTED_HORIZONS:
        return self._clarification_response(
            "Actualmente puedo predecir la demanda de los próximos 7 días. El horizonte solicitado todavía no está disponible."
        )
    if intent.horizon_days is not None:
        context["horizonte_dias_solicitado"] = intent.horizon_days
        context["tipo_prediccion"] = "demanda"
    if data.id_inventario and user is not None:
        context["inventario"] = await self._authorized_tool("get_inventory", {"id_inventario": data.id_inventario}, user)
    if data.id_producto and user is not None:
        context["producto"] = await self._authorized_tool("get_product", {"id_producto": data.id_producto}, user)
    if intent.kind in {"product_quantities", "inventory_detail"} and not data.id_producto and not data.id_inventario:
        return await self._fast_detail_response(data, context, user, intent.kind)
    if intent.kind in {"alerts", "movements", "recommendations"} and not data.id_producto:
        return await self._fast_operational_response(intent.kind, data, context, user)
    if intent.kind in {"predictive", "risk"} and not re.search(r"\b(?:alerta|movimiento|recomend|comprar)", self.intent_router._normalize(data.message or "")):
        return await self._fast_analysis_response(intent.kind, data, context, user)
    if intent.kind == "products" and not data.id_inventario and not data.id_producto:
        return await self._fast_products_response(data, context, user)
    location_name = self._location_name(data.message or "") if intent.kind == "location" else None
    if location_name and not data.id_inventario and not data.id_producto:
        return await self._fast_location_response(location_name, context, user)
    if (
        intent.kind in {"general", "product_count", "warehouses", "stock_total"}
        and not data.id_inventario
        and not data.id_producto
    ):
        try:
            return await self._fast_current_response(context, user, intent.kind, data)
        except SaikiDatabaseError as exc:
            raise HTTPException(
                status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
                detail="No se pudo verificar el inventario en MongoDB.",
            ) from exc
        except RuntimeError as exc:
            logger.exception("saiki_request_error type=unexpected_runtime")
            raise HTTPException(
                status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
                detail="Saiki no está disponible en este momento.",
            ) from exc
    analysis_data, analysis_sources = {}, set()
    if intent.kind == "analysis":
        summary, summary_source = await self._execute_tool("get_warehouse_status", {"include_visual": True}, user)
        recommendations, recommendation_source = await self._execute_tool("get_recommendations", {}, user)
        analysis_data = {"get_warehouse_status": summary, "get_recommendations": recommendations}
        analysis_sources = {summary_source, recommendation_source}
        context["datos_verificados_analisis"] = analysis_data
    messages = [
        {"role": "system", "content": self.get_system_prompt()},
        *data.history,
        {
            "role": "user",
            "content": self._build_prompt(data.message or "", context),
        },
    ]
    started = time.perf_counter()
    try:
        answer, tool_data, sources = await self._agent_loop(messages, user, intent.tool_names or None)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    except OllamaTimeoutError as exc:
        logger.warning("saiki_request_error type=ollama_timeout")
        raise HTTPException(
            status_code=status.HTTP_504_GATEWAY_TIMEOUT,
            detail="Ollama tardó demasiado en responder.",
        ) from exc
    except OllamaUnavailableError as exc:
        logger.warning("saiki_request_error type=ollama_unavailable")
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail="Ollama no está disponible en este momento.",
        ) from exc
    except SaikiDatabaseError as exc:
        logger.warning("saiki_request_error type=mongodb_unavailable")
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail="No se pudo verificar el inventario en MongoDB.",
        ) from exc
    except RuntimeError as exc:
        logger.exception("saiki_request_error type=unexpected_runtime")
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail="Saiki no está disponible en este momento.",
        ) from exc
    finally:
        logger.info(
            "saiki_request duration_ms=%d",
            round((time.perf_counter() - started) * 1000),
        )

    if analysis_data:
        tool_data = {**analysis_data, **tool_data}
        sources.update(analysis_sources)
    if "LIGHTGBM" in sources and intent.horizon_days == 7:
        answer = "La proyección corresponde a la demanda de los próximos 7 días. " + answer
    return {
        "answer": answer,
        "model": self.settings.ollama_model,
        "base_url": self.settings.ollama_base_url,
        "source": "ollama",
        "context": context,
        "data": tool_data,
        "visualization": self._visualization(tool_data),
        "sources": sorted(sources),
        "warnings": self._warnings(sources, tool_data),
    }

async def _fast_operational_response(self, kind, request_data, context, user):
    tool = {"alerts": "get_active_alerts", "movements": "get_recent_movements", "recommendations": "get_recommendations"}[kind]
    arguments = {"id_inventario": request_data.id_inventario} if request_data.id_inventario else {}
    rows, source = await self._execute_tool(tool, arguments, user)
    text = self.intent_router._normalize(request_data.message or "")
    if kind == "movements" and re.search(r"\bsalidas?\b|\bentradas?\b", text):
        movement_type = "SALIDA" if re.search(r"\bsalidas?\b", text) else "ENTRADA"
        rows = [row for row in rows if row.get("tipo_movimiento") == movement_type]
        answer = f"Encontré {len(rows)} {movement_type.lower()}{'s' if len(rows) != 1 else ''} entre los movimientos recientes consultados."
    else:
        answer = operational_answer(kind, rows)
    return self._verified_response(answer, context, {tool: rows}, {source})

async def _fast_products_response(self, request_data, context, user):
    text = self.intent_router._normalize(request_data.message or "")
    if re.search(r"quedan|disponibles|existencias", text):
        summary, source = await self._execute_tool("get_warehouse_status", {}, user)
        products = [row for row in summary.get("stock_por_producto", []) if row.get("stock_actual", 0) > 0]
        details = "; ".join(f"{row.get('nombre') or 'Producto sin nombre'}: {row['stock_actual']} unidades" for row in products[:5])
        answer = f"Tienes estas existencias: {details}." if products else "No encontré productos con existencias positivas en tus inventarios visibles."
        if len(products) == 1:
            answer = f"Quedan {products[0]['stock_actual']} unidades de {products[0].get('nombre') or 'un producto sin nombre registrado'}."
        if len(products) > 5:
            answer += " Puedes consultar el resto en los datos adjuntos."
        return self._verified_response(answer, context, {"get_warehouse_status": summary}, {source})
    products, source = await self._execute_tool("get_product", {}, user)
    selected = self._product_from_history(products, [{"role": "user", "content": request_data.message or ""}])
    if selected:
        context["producto_consultado"] = {"id_producto": selected["id_producto"], "nombre": selected.get("nombre")}
        answer = f"{selected.get('nombre') or 'El producto'} está registrado en tu catálogo."
    elif "muestrame" in text:
        answer = "No pude identificar un único producto de tu catálogo. Indica su nombre completo para consultarlo."
    else:
        answer = f"Tienes {len(products)} {'producto registrado' if len(products) == 1 else 'productos registrados'} en tu catálogo."
    return self._verified_response(answer, context, {"get_product": products}, {source})

def _product_from_history(self, products, history):
    for item in reversed((history or [])[-4:]):
        if item.get("role") != "user":
            continue
        text = self.intent_router._normalize(str(item.get("content", "")))
        matches = [product for product in products if product.get("nombre") and re.search(r"\b" + re.escape(self.intent_router._normalize(product["nombre"])) + r"\b", text)]
        if len(matches) == 1:
            return matches[0]
        if len(matches) > 1:
            return None
    return None

async def _fast_analysis_response(self, kind, request_data, context, user):
    arguments = {"id_inventario": request_data.id_inventario} if request_data.id_inventario else {}
    summary, source = await self._execute_tool("get_warehouse_status", arguments, user)
    data, sources = {"get_warehouse_status": summary}, {source}
    inventories = summary.get("inventarios", [])
    if request_data.id_producto:
        product, product_source = await self._execute_tool("get_product", {"id_producto": request_data.id_producto}, user)
        sources.add(product_source)
        data["get_product"] = product
        inventories = [row for row in inventories if row.get("id_producto") == request_data.id_producto]
    elif request_data.history:
        products, product_source = await self._execute_tool("get_product", {}, user)
        sources.add(product_source)
        data["get_product"] = products
        product = self._product_from_history(products, request_data.history)
        if product:
            inventories = [row for row in inventories if row.get("id_producto") == product["id_producto"]]
            context["producto_consultado"] = {"id_producto": product["id_producto"], "nombre": product.get("nombre")}
        elif any(item.get("role") == "user" and re.search(r"muestrame|donde", self.intent_router._normalize(str(item.get("content", "")))) for item in request_data.history[-4:]):
            return self._verified_response("No pude identificar un único producto de tu catálogo en el historial. ¿Qué producto deseas consultar?", context, data, sources)
    if not inventories:
        return self._verified_response("No hay inventarios visibles para calcular esta consulta. Registra existencias o indica un producto con inventario.", context, data, sources)
    text = self.intent_router._normalize(request_data.message or "")
    is_risk = kind == "risk" or bool(re.search(r"agot|riesgo|desabastec", text))
    if not is_risk and len(inventories) != 1:
        return self._verified_response("¿Para qué producto y ubicación deseas consultar la demanda de los próximos 7 días?", context, data, sources)
    if not is_risk:
        forecast, forecast_source = await self._execute_tool("get_forecast", {"id_inventario": inventories[0]["id_inventario"], "horizonte_dias": 7}, user)
        data["get_forecast"] = forecast
        sources.add(forecast_source)
        return self._verified_response(forecast_answer(forecast), context, data, sources)
    results = []
    product_names = {row.get("id_producto"): row.get("nombre") for row in summary.get("stock_por_producto", [])}
    for inventory in inventories:
        result, risk_source = await self._execute_tool("get_inventory_risk", {"id_inventario": inventory["id_inventario"]}, user)
        result = dict(result)
        if product_names.get(inventory.get("id_producto")):
            result["nombre_producto"] = product_names[inventory["id_producto"]]
        results.append(result)
        sources.add(risk_source)
    data["get_inventory_risk"] = results[0] if len(results) == 1 else results
    response = self._verified_response(risk_answer(results), context, data, sources)
    if summary.get("total_registros_inventario", len(inventories)) > len(summary.get("inventarios", [])):
        response["warnings"].append("El riesgo se evaluó solo para los inventarios incluidos en el resumen; no representa todos los inventarios.")
    return response

def _location_name(message: str) -> str | None:
    match = re.search(r"(?:d[oó]nde\s+(?:est[aá]n?|se\s+encuentran?)|ubicaci[oó]n\s+de)\s+(?:(?:el|la|los|las|producto)\s+)?(.+?)[?!.]*$", message, re.IGNORECASE)
    if not match:
        return None
    name = match[1].strip()
    if re.search(r"\b(?:y|o|en|cu[aá]nt|explica|busco)\b", name, re.IGNORECASE):
        return None
    return name or None

async def _fast_location_response(self, name: str, context: dict, user) -> dict:
    products, source = await self._execute_tool("get_product", {}, user)
    normalized = self.intent_router._normalize(name)
    matches = [product for product in products if self.intent_router._normalize(product.get("nombre", "")) == normalized]
    if not matches:
        matches = [product for product in products if re.search(r"\b" + re.escape(normalized) + r"\b", self.intent_router._normalize(product.get("nombre", "")))]
    data = {"get_product": products}
    sources = {source}
    if not matches:
        answer = f"No encontré {name} en el catálogo de tu empresa."
    elif len(matches) > 1:
        answer = f"Encontré varios productos que coinciden con {name}. ¿Cuál deseas localizar?"
    else:
        summary, inventory_source = await self._execute_tool("get_warehouse_status", {}, user)
        data["get_warehouse_status"] = summary
        sources.add(inventory_source)
        product = matches[0]
        locations = [item for item in summary.get("ubicaciones", []) if item.get("id_producto") == product["id_producto"]]
        if not locations:
            answer = f"{product['nombre']} está registrado, pero no encontré una ubicación de inventario en tus almacenes visibles."
        elif len(locations) == 1:
            rack = locations[0].get("rack") or {}
            label = rack.get("codigo") or rack.get("nombre")
            answer = f"{product['nombre']} está en el rack {label}." if label else f"{product['nombre']} tiene una ubicación registrada; puedes consultarla en el detalle de inventario."
        else:
            answer = f"{product['nombre']} está distribuido en {len(locations)} ubicaciones. Puedes consultar los racks en el detalle de inventario."
    response = self._simple_response(answer, "backend", data)
    response.update(context=context, sources=sorted(sources))
    logger.info("saiki_agent_summary ollama_calls=0 tool_calls=%d source=backend", len(data))
    return response

async def _fast_current_response(self, context: dict, user, kind="general", request_data=None) -> dict:
    started = time.perf_counter()
    tool = "get_product" if kind == "product_count" else "get_warehouse_status"
    try:
        result, source = await self._execute_tool(
            tool, ({"include_visual": True, "page": getattr(request_data, "page", 1), "page_size": getattr(request_data, "page_size", 25)} if kind == "general" and request_data is not None else {}), user
        )
    except RuntimeError as exc:
        if "MongoDB" in str(exc) or "motor" in str(exc):
            raise SaikiDatabaseError(str(exc)) from exc
        raise
    finally:
        logger.info(
            "saiki_fast_path tool=%s duration_ms=%d",
            tool,
            round((time.perf_counter() - started) * 1000),
        )
    if kind == "product_count":
        answer = f"Tienes {len(result)} {'producto registrado' if len(result) == 1 else 'productos registrados'} en tu catálogo."
    elif kind == "warehouses":
        count = result["total_almacenes"]
        answer = f"Tienes {count} {'almacén registrado' if count == 1 else 'almacenes registrados'} en PsiTwin." if count else "Actualmente no tienes almacenes registrados en PsiTwin. Te recomiendo crear tu primer almacén."
    elif kind == "stock_total":
        answer = f"Actualmente tienes {result['stock_total_unidades']} unidades en tu inventario."
    else:
        answer = self._natural_inventory_answer(result)
        if result.get("estado_inventario") == "stock_positivo" and "inventory_summary" in result:
            summary = result["inventory_summary"]
            products_label = "producto diferente" if summary['distinct_products'] == 1 else "productos diferentes"
            warehouses_label = "almacén" if summary['warehouse_count'] == 1 else "almacenes"
            answer = f"Actualmente tienes {summary['distinct_products']} {products_label} y {summary['total_units']} unidades distribuidas en {summary['warehouse_count']} {warehouses_label}."
    payload_data = {tool: result}
    visualization = {"type": "none"}
    if "inventory_summary" in result and kind == "general":
        payload_data["inventory_summary"] = result["inventory_summary"]
        visualization = result["visualization"]
    logger.info("saiki_agent_summary ollama_calls=0 tool_calls=1 source=backend")
    return {
        "answer": answer,
        "model": self.settings.ollama_model,
        "base_url": self.settings.ollama_base_url,
        "source": "backend",
        "context": context,
        "data": payload_data,
        "visualization": visualization,
        "sources": [source],
        "warnings": [],
    }

def _natural_inventory_answer(result: dict) -> str:
    state = result.get("estado_inventario")
    if state == "sin_almacenes":
        return (
            "Actualmente no tienes almacenes registrados en PsiTwin. Te "
            "recomiendo crear tu primer almacén para comenzar a gestionar "
            "el inventario."
        )
    if state == "almacen_sin_productos":
        return (
            "Tu almacén está registrado, pero todavía no tienes productos "
            "registrados."
        )
    if state == "productos_sin_inventario":
        return (
            "Tienes productos registrados, pero todavía no hay existencias "
            "de inventario asociadas."
        )
    if state == "stock_cero":
        return (
            "Tienes productos registrados, pero actualmente sus existencias "
            "son cero."
        )
    if state == "stock_positivo":
        products = result.get("productos_distintos", 0)
        units = result.get("stock_total_unidades", 0)
        return (
            f"Actualmente tienes {products} {'producto distinto' if products == 1 else 'productos distintos'} y "
            f"{units} {'unidad registrada' if units == 1 else 'unidades registradas'} en tu inventario."
        )
    raise RuntimeError("La consulta de inventario no devolvió un estado válido.")

async def _execute_tool(self, name, arguments, user=None):
    if user is None:
        return await self.tools.execute(name, arguments)
    return await self.tools.execute(name, arguments, user)

def _clean_answer(answer: str) -> str:
    if "</think>" in answer:
        answer = answer.rsplit("</think>", 1)[1]
    if "<think>" in answer:
        answer = answer.split("<think>", 1)[0]
    return answer.strip()

def _parse_tool_call(self, tool_call: object) -> tuple[str, dict]:
    if not isinstance(tool_call, dict):
        raise ValueError("Tool call inválida.")
    function = tool_call.get("function")
    if not isinstance(function, dict) or not isinstance(function.get("name"), str):
        raise ValueError("Tool call inválida.")
    arguments = function.get("arguments", {})
    if isinstance(arguments, str):
        try:
            arguments = json.loads(arguments)
        except json.JSONDecodeError as exc:
            raise ValueError("Los argumentos de la tool no son JSON válido.") from exc
    if not isinstance(arguments, dict):
        raise ValueError("Los argumentos de la tool deben ser un objeto.")
    return function["name"], arguments

def _build_prompt(question: str, context: dict) -> str:
    return (
        "Usa únicamente el contexto y las tools autorizadas. No inventes datos. "
        "Si falta información, dilo claramente.\n\n"
        f"CONTEXTO PSI TWIN:\n{json.dumps(context, ensure_ascii=False, default=str, indent=2)}"
        f"\n\nPREGUNTA:\n{question}"
    )

def _warnings(sources: set[str], data: dict | None = None) -> list[str]:
    warnings = []
    if "INVENTORY_RISK" in sources:
        warnings.append("El riesgo proviene de InventoryRiskService.")
    if "LIGHTGBM" in sources:
        warnings.append("La predicción proviene del pipeline LightGBM.")
        warnings.append("La predicción depende del historial disponible y representa demanda, no stock futuro.")
        forecast = (data or {}).get("get_forecast")
        if isinstance(forecast, dict) and any(item.get("sin_datos", 0) > 0 for item in forecast.get("features_por_horizonte", {}).values() if isinstance(item, dict)):
            warnings.append("Hay variables sin datos en el modelo; interpreta la predicción con esa limitación.")
    return warnings

def definitions(
    self,
    names: set[str] | frozenset[str] | None = None,
) -> list[dict[str, Any]]:
    return [
        {
            "type": "function",
            "function": {
                "name": name,
                "description": (
                    "Consulta de solo lectura. "
                    + (
                        "Para un resumen general del almacén no requiere argumentos."
                        if name == "get_warehouse_status"
                        else f"Tool autorizada: {name}."
                    )
                ),
                "parameters": model.model_json_schema(),
            },
        }
        for name, (model, _, _) in self._handlers.items()
        if names is None or name in names
    ]

async def execute(
    self,
    name: str,
    arguments: dict[str, Any],
    user=None,
) -> tuple[Any, str]:
    if name not in self._handlers:
        raise ValueError(f"Tool no autorizada: {name}")
    model, handler, source = self._handlers[name]
    try:
        validated = model.model_validate(arguments)
    except Exception as exc:
        raise ValueError(f"Argumentos inválidos para {name}: {exc}") from exc
    visible = None
    started = time.perf_counter()
    if user is not None:
        visible = await self._authorize(name, validated, user)
    logger.info("saiki_authorization tool=%s duration_ms=%.3f", name, (time.perf_counter() - started) * 1000)
    started = time.perf_counter()
    try:
        if name == "get_warehouse_status":
            return await handler(validated, user, visible), source
        if name == "get_product":
            return await handler(validated, user), source
        if name in {"get_active_alerts", "get_recommendations", "get_recent_movements"}:
            return await handler(validated, visible), source
        return await handler(validated), source
    finally:
        logger.info("saiki_data_query tool=%s duration_ms=%.3f", name, (time.perf_counter() - started) * 1000)

async def _authorize(self, name: str, args: BaseModel, user):
    if name == "get_warehouse_status" and getattr(args, "include_visual", False) and not args.id_inventario:
        # The visual summary traverses the authorized hierarchy once itself.
        return None
    visible = frozenset(await AccesoService.ids_inventarios(user))
    if hasattr(args, "id_inventario") and args.id_inventario:
        await AccesoService.verificar_inventario(user, args.id_inventario)
    if name == "get_product" and args.id_producto:
        await AccesoService.verificar_producto(user, args.id_producto)
    return visible

async def get_product(self, args: ProductArgs, user=None):
    if args.id_producto:
        return await ProductoRepository.obtener_por_id(args.id_producto)
    products = await ProductoRepository.obtener_todos()
    return [item for item in products if user is None or item.get("id_empresa") == user.id_empresa]

async def get_inventory_risk(self, args: InventoryArgs):
    result = await self.risk_service.evaluar(
        id_inventario=args.id_inventario,
        generar_alertas=False,
    )
    return result.model_dump(mode="python")

async def get_recommendations(self, args: OptionalInventoryArgs, visible=None):
    if args.id_inventario:
        return await self.recomendacion_service.listar_por_inventario(
            args.id_inventario
        )
    recommendations = await self.recomendacion_service.listar()
    return [
        item
        for item in recommendations
        if visible is None or item.get("id_inventario") in visible
    ]

async def get_recent_movements(self, args: OptionalInventoryArgs, visible=None):
    if args.id_inventario:
        movements = await self.movimiento_service.obtener_por_inventario(args.id_inventario)
    else:
        movements = await self.movimiento_service.obtener_movimientos()
        movements = [item for item in movements if visible is None or item.get("id_inventario") in visible]
    return sorted(
        movements,
        key=lambda item: str(item.get("fecha_hora", "")),
        reverse=True,
    )[:20]

async def get_warehouse_status(
    self,
    args: OptionalInventoryArgs,
    user: UsuarioActual | None = None,
    visible=None,
):
    if getattr(args, "include_visual", False):
        from app.services.saiki_inventory_summary import inventory_summary
        return await inventory_summary(user, args.page, args.page_size)
    visible_warehouse_ids = None
    if user is not None:
        visible_warehouse_ids = await AccesoService.ids_almacenes(user)
    warehouses = await AlmacenRepository.obtener_todos()
    if visible_warehouse_ids is not None:
        warehouses = [
            warehouse
            for warehouse in warehouses
            if (warehouse.get("id_almacen") or warehouse.get("id"))
            in visible_warehouse_ids
        ]
    if not warehouses:
        return {
            "estado_inventario": "sin_almacenes",
            "total_almacenes": 0,
            "mensaje": (
                "Actualmente no tienes almacenes registrados en PsiTwin. "
                "Primero debes crear uno para comenzar a gestionar tu inventario."
            ),
            "total_registros_inventario": 0,
            "productos_distintos": 0,
            "stock_total_unidades": 0,
            "almacenes": [],
            "stock_por_producto": [],
            "ubicaciones": [],
            "inventarios": [],
        }

    if visible_warehouse_ids is not None:
        visible_zone_ids = {
            zone.get("id_zona", zone.get("id"))
            for zone in await ZonaRepository.obtener_todas()
            if zone.get("id_almacen") in visible_warehouse_ids
        }
        visible_rack_ids = {
            rack.get("id_rack") or rack.get("id")
            for rack in await RackRepository.obtener_todos()
            if rack.get("id_zona") in visible_zone_ids
        }
    else:
        visible_rack_ids = None

    inventories = await self.inventario_service.obtener_inventarios()
    if visible is not None:
        inventories = [
            item for item in inventories
            if item.get("id_inventario") in visible
        ]
    if args.id_inventario:
        inventories = [
            item for item in inventories
            if item.get("id_inventario") == args.id_inventario
        ]

    if visible_rack_ids is not None:
        inventories = [
            item for item in inventories
            if item.get("id_rack") in visible_rack_ids
        ]

    product_ids = {
        item.get("id_producto")
        for item in inventories
        if item.get("id_producto")
    }
    all_products = await ProductoRepository.obtener_todos()
    products = {
        product["id_producto"]: product
        for product in all_products
        if (
            product.get("id_producto") in product_ids
            or visible_rack_ids is None
            or (user is not None and product.get("id_empresa") == user.id_empresa)
        )
    }
    if not inventories and not products:
        return {
            "estado_inventario": "almacen_sin_productos",
            "total_almacenes": len(warehouses),
            "mensaje": (
                "Tu almacén está registrado, pero todavía no tienes "
                "productos registrados."
            ),
            "total_registros_inventario": 0,
            "productos_distintos": 0,
            "stock_total_unidades": 0,
            "almacenes": warehouses,
            "stock_por_producto": [],
            "ubicaciones": [],
            "inventarios": [],
        }
    if not inventories:
        return {
            "estado_inventario": "productos_sin_inventario",
            "total_almacenes": len(warehouses),
            "mensaje": (
                "Tienes productos registrados, pero todavía no hay "
                "existencias de inventario asociadas."
            ),
            "total_registros_inventario": 0,
            "productos_distintos": len(products),
            "stock_total_unidades": 0,
            "almacenes": warehouses,
            "stock_por_producto": [],
            "ubicaciones": [],
            "inventarios": [],
        }
    rack_ids = {
        item.get("id_rack")
        for item in inventories
        if item.get("id_rack")
    }
    racks = {
        (rack.get("id_rack") or rack.get("id")): rack
        for rack in await RackRepository.obtener_todos()
        if (rack.get("id_rack") or rack.get("id")) in rack_ids
    }
    zone_ids = {
        rack.get("id_zona")
        for rack in racks.values()
        if rack.get("id_zona")
    }
    zones = {
        zone.get("id_zona", zone.get("id")): zone
        for zone in await ZonaRepository.obtener_todas()
        if zone.get("id_zona", zone.get("id")) in zone_ids
    }
    warehouse_ids = {
        zone.get("id_almacen")
        for zone in zones.values()
        if zone.get("id_almacen")
    }
    warehouses_by_id = {
        almacen.get("id_almacen", almacen.get("id")): almacen
        for almacen in warehouses
        if almacen.get("id_almacen", almacen.get("id")) in warehouse_ids
    }
    stock_by_product: dict[str, int | float] = {}
    for item in inventories:
        product_id = item.get("id_producto")
        stock_by_product[product_id] = (
            stock_by_product.get(product_id, 0)
            + (item.get("stock_actual", 0) or 0)
        )

    result = {
        "total_almacenes": len(warehouses),
        "total_registros_inventario": len(inventories),
        "productos_distintos": len(product_ids),
        "stock_total_unidades": sum(stock_by_product.values()),
        "stock_por_producto": [
            {
                "id_producto": product_id,
                "nombre": products.get(product_id, {}).get("nombre"),
                "stock_actual": stock,
            }
            for product_id, stock in stock_by_product.items()
        ],
        "almacenes": list(warehouses_by_id.values()),
        "ubicaciones": [
            {
                "id_inventario": item.get("id_inventario"),
                "id_producto": item.get("id_producto"),
                "id_rack": item.get("id_rack"),
                "rack": racks.get(item.get("id_rack")),
                "zona": zones.get(
                    racks.get(item.get("id_rack"), {}).get("id_zona")
                ),
                "stock_actual": item.get("stock_actual", 0),
            }
            for item in inventories
        ],
        "inventarios": inventories[:50],
    }
    if all(stock <= 0 for stock in stock_by_product.values()):
        result["estado_inventario"] = "stock_cero"
        result["mensaje"] = (
            "Tienes productos registrados, pero actualmente sus existencias son cero."
        )
    else:
        result["estado_inventario"] = "stock_positivo"
    return result

async def normalizar_zona(
    zona: Dict[str, Any]
) -> Dict[str, Any]:

    if not zona:

        return zona

    result = dict(
        zona
    )

    # --------------------------------------------------------
    # ID ANTIGUO
    # --------------------------------------------------------

    if (
        "id" not in result
        and
        "id_zona" in result
    ):

        result["id"] = (
            result["id_zona"]
        )

    # --------------------------------------------------------
    # COMPLETAR ID_EMPRESA DESDE ALMACEN
    # --------------------------------------------------------

    if (
        not result.get("id_empresa")
        and
        result.get("id_almacen")
    ):

        almacen = await (
            AlmacenRepository.obtener_por_id(
                result["id_almacen"]
            )
        )

        if almacen:

            result["id_empresa"] = (
                almacen.get(
                    "id_empresa"
                )
            )

    return result


# ============================================================
# CREAR
# ============================================================

async def obtener_por_id(
    id_zona: str
) -> Dict[str, Any]:

    zona = await (
        ZonaRepository.obtener_por_id(
            id_zona
        )
    )

    if not zona:

        raise HTTPException(
            status_code=(
                status.HTTP_404_NOT_FOUND
            ),
            detail=(
                "Zona no encontrada"
            )
        )

    return await (
        ZonaService.normalizar_zona(
            zona
        )
    )


# ============================================================
# OBTENER POR ALMACEN
# ============================================================

async def obtener_por_almacen(
    id_almacen: str
) -> List[Dict[str, Any]]:

    almacen = await (
        AlmacenRepository.obtener_por_id(
            id_almacen
        )
    )

    if not almacen:

        raise HTTPException(
            status_code=(
                status.HTTP_404_NOT_FOUND
            ),
            detail=(
                "Almacén no encontrado"
            )
        )

    zonas = await (
        ZonaRepository.obtener_por_almacen(
            id_almacen
        )
    )

    result = []

    for zona in zonas:

        zona_normalizada = await (
            ZonaService.normalizar_zona(
                zona
            )
        )

        result.append(
            zona_normalizada
        )

    return result


# ============================================================
# ACTUALIZAR
# ============================================================

async def actualizar(
    id_zona: str,
    data: ZonaUpdate
) -> Dict[str, Any]:

    zona_actual = await (
        ZonaRepository.obtener_por_id(
            id_zona
        )
    )

    if not zona_actual:

        raise HTTPException(
            status_code=(
                status.HTTP_404_NOT_FOUND
            ),
            detail=(
                "Zona no encontrada"
            )
        )

    update_data = (
        data.model_dump(
            exclude_unset=True
        )
    )

    if not update_data:

        return await (
            ZonaService.normalizar_zona(
                zona_actual
            )
        )

    temperatura_min = (
        update_data.get(
            "temperatura_min",
            zona_actual.get(
                "temperatura_min"
            )
        )
    )

    temperatura_max = (
        update_data.get(
            "temperatura_max",
            zona_actual.get(
                "temperatura_max"
            )
        )
    )

    if (
        temperatura_min is not None
        and
        temperatura_max is not None
        and
        temperatura_min
        >
        temperatura_max
    ):

        raise HTTPException(
            status_code=(
                status.HTTP_400_BAD_REQUEST
            ),
            detail=(
                "La temperatura mínima "
                "no puede ser mayor "
                "que la máxima"
            )
        )

    updated = await (
        ZonaRepository.actualizar(
            id_zona,
            update_data
        )
    )

    if not updated:

        raise HTTPException(
            status_code=(
                status.HTTP_404_NOT_FOUND
            ),
            detail=(
                "Zona no encontrada"
            )
        )

    return await (
        ZonaService.normalizar_zona(
            updated
        )
    )


# ============================================================
# ELIMINAR
# ============================================================

async def eliminar(
    id_zona: str
) -> Dict[str, str]:

    zona = await (
        ZonaRepository.obtener_por_id(
            id_zona
        )
    )

    if not zona:

        raise HTTPException(
            status_code=(
                status.HTTP_404_NOT_FOUND
            ),
            detail=(
                "Zona no encontrada"
            )
        )

    deleted = await (
        ZonaRepository.eliminar(
            id_zona
        )
    )

    if not deleted:

        raise HTTPException(
            status_code=(
                status.HTTP_500_INTERNAL_SERVER_ERROR
            ),
            detail=(
                "No se pudo eliminar "
                "la zona"
            )
        )

    return {
        "mensaje":
            "Zona eliminada correctamente"
    }

def hash_password(
    password: str
) -> str:

    hashed = bcrypt.hashpw(
        password.encode(
            "utf-8"
        ),
        bcrypt.gensalt()
    )

    return hashed.decode(
        "utf-8"
    )

def create_access_token(
    sub: str,
    rol: str = ROL_EMPRESA,
    id_empresa: Optional[str] = None,
    id_almacen: Optional[str] = None,
    id_proveedor: Optional[str] = None
) -> str:

    now = datetime.now(
        timezone.utc
    )

    expiration = (
        now
        +
        timedelta(
            minutes=(
                settings
                .access_token_expire_minutes
            )
        )
    )

    payload: Dict[str, Any] = {

        "sub": sub,

        "rol": rol,

        "type": rol.lower(),

        "id_empresa": (
            id_empresa
            or
            sub
        ),

        "iat": now,

        "exp": expiration
    }

    if rol == ROL_OPERARIO:

        payload[
            "id_almacen"
        ] = id_almacen

    if rol == ROL_PROVEEDOR:

        payload[
            "id_proveedor"
        ] = id_proveedor

    return jwt.encode(
        payload,
        settings.secret_key,
        algorithm=settings.algorithm
    )

def decode_access_token(
    token: str
) -> Dict[str, Any]:

    # Lanza jwt.ExpiredSignatureError /
    # jwt.InvalidTokenError; quien llama
    # decide el HTTP status.

    return jwt.decode(
        token,
        settings.secret_key,
        algorithms=[
            settings.algorithm
        ]
    )

