app/controllers/orden_reposicion_control.source:
from typing import List

from fastapi import APIRouter, Depends, HTTPException, status

from app.dependencies.dependencies import (
    get_usuario_activo,
    require_empresa,
    require_empresa_u_operario,
    require_operario,
    require_proveedor
)

from app.dto.auth_dto import (
    UsuarioActual
)

from app.dto.orden_reposicion_dto import (
    OrdenReposicionCreate,
    OrdenReposicionUpdate,
    OrdenReposicionResponse,
    EstadoOrdenReposicion,
    DevolverOrdenRequest,
    DespachoRequest
)

from app.services.acceso_service import (
    AccesoService
)

from app.services.orden_reposicion_service import (
    OrdenReposicionService
)


# ============================================================
# SOLICITUD / ORDEN DE REPOSICION
#
# PENDIENTE -> (OBSERVADA <-> PENDIENTE) -> ENVIADA
#           -> PARCIAL -> RECIBIDA ; CANCELADA
#
# OPERARIO : crea y edita (PENDIENTE / OBSERVADA), reenvía;
#            lee las de su almacén.
# EMPRESA  : valida (-> ENVIADA), devuelve con comentario
#            (-> OBSERVADA), cancela; lee todas las suyas.
# PROVEEDOR: lee las ENVIADAS a él y registra el despacho.
# ============================================================

router = APIRouter(
    prefix="/ordenes-reposicion",
    tags=["Ordenes de Reposicion"]
)

service = OrdenReposicionService()


def _alcance(
    user: UsuarioActual,
    ordenes: list
) -> list:

    ordenes = AccesoService.filtrar_empresa(
        user,
        ordenes
    )

    if user.es_operario:

        ordenes = [
            orden
            for orden in ordenes
            if orden.get("id_almacen")
            == user.id_almacen
        ]

    return ordenes


# ============================================================
# CREAR SOLICITUD (OPERARIO)
#
# Almacén = el del operario. Queda PENDIENTE.
# ============================================================

@router.post(
    "",
    response_model=OrdenReposicionResponse,
    status_code=status.HTTP_201_CREATED
)
async def crear(
    data: OrdenReposicionCreate,
    user: UsuarioActual = Depends(require_operario)
):
    if not user.id_almacen:
        raise HTTPException(
            status_code=409,
            detail="El operario no tiene almacén asignado"
        )

    data.id_empresa = user.id_empresa
    data.id_almacen = user.id_almacen
    data.id_recomendacion = None

    return await service.crear(
        data,
        user.id_operario
    )


@router.get(
    "",
    response_model=List[OrdenReposicionResponse]
)
async def obtener_todos(
    user: UsuarioActual = Depends(require_empresa_u_operario)
):
    return _alcance(
        user,
        await service.obtener_por_empresa(
            user.id_empresa
        )
    )


# ============================================================
# ORDENES ENVIADAS AL PROVEEDOR AUTENTICADO
#
# IMPORTANTE: antes de /proveedor/{id_proveedor}
# ============================================================

@router.get(
    "/proveedor/me",
    response_model=List[OrdenReposicionResponse]
)
async def obtener_proveedor_me(
    user: UsuarioActual = Depends(require_proveedor)
):
    return await service.obtener_para_proveedor(
        user.id_proveedor
    )


@router.get(
    "/empresa/{id_empresa}",
    response_model=List[OrdenReposicionResponse]
)
async def obtener_por_empresa(
    id_empresa: str,
    user: UsuarioActual = Depends(require_empresa_u_operario)
):
    AccesoService.verificar_empresa(user, id_empresa)
    return _alcance(
        user,
        await service.obtener_por_empresa(id_empresa)
    )


@router.get(
    "/almacen/{id_almacen}",
    response_model=List[OrdenReposicionResponse]
)
async def obtener_por_almacen(
    id_almacen: str,
    user: UsuarioActual = Depends(require_empresa_u_operario)
):
    await AccesoService.verificar_almacen(user, id_almacen)
    return await service.obtener_por_almacen(id_almacen)


@router.get(
    "/proveedor/{id_proveedor}",
    response_model=List[OrdenReposicionResponse]
)
async def obtener_por_proveedor(
    id_proveedor: str,
    user: UsuarioActual = Depends(require_empresa_u_operario)
):
    await AccesoService.verificar_proveedor(user, id_proveedor)
    return _alcance(
        user,
        await service.obtener_por_proveedor(id_proveedor)
    )


@router.get(
    "/estado/{estado}",
    response_model=List[OrdenReposicionResponse]
)
async def obtener_por_estado(
    estado: EstadoOrdenReposicion,
    user: UsuarioActual = Depends(require_empresa_u_operario)
):
    return _alcance(
        user,
        await service.obtener_por_estado(
            estado.value
        )
    )


# ============================================================
# VALIDAR (EMPRESA) -> ENVIADA
#
# aprobar / enviar: alias antiguos de validar.
# ============================================================

@router.patch(
    "/{id_orden}/validar",
    response_model=OrdenReposicionResponse
)
@router.patch(
    "/{id_orden}/aprobar",
    response_model=OrdenReposicionResponse,
    deprecated=True
)
@router.patch(
    "/{id_orden}/enviar",
    response_model=OrdenReposicionResponse,
    deprecated=True
)
async def validar(
    id_orden: str,
    user: UsuarioActual = Depends(require_empresa)
):
    await AccesoService.verificar_orden(user, id_orden)
    return await service.validar(id_orden)


# ============================================================
# DEVOLVER CON COMENTARIO (EMPRESA) -> OBSERVADA
# ============================================================

@router.patch(
    "/{id_orden}/devolver",
    response_model=OrdenReposicionResponse
)
async def devolver(
    id_orden: str,
    data: DevolverOrdenRequest,
    user: UsuarioActual = Depends(require_empresa)
):
    await AccesoService.verificar_orden(user, id_orden)
    return await service.devolver(
        id_orden,
        data.comentario
    )


# ============================================================
# REENVIAR (OPERARIO): OBSERVADA -> PENDIENTE
# ============================================================

@router.patch(
    "/{id_orden}/reenviar",
    response_model=OrdenReposicionResponse
)
async def reenviar(
    id_orden: str,
    user: UsuarioActual = Depends(require_operario)
):
    await AccesoService.verificar_orden(user, id_orden)
    return await service.reenviar(id_orden)


@router.patch(
    "/{id_orden}/cancelar",
    response_model=OrdenReposicionResponse
)
async def cancelar(
    id_orden: str,
    user: UsuarioActual = Depends(require_empresa)
):
    await AccesoService.verificar_orden(user, id_orden)
    return await service.cancelar(id_orden)


# ============================================================
# REGISTRAR DESPACHO (PROVEEDOR)
# ============================================================

@router.post(
    "/{id_orden}/despacho",
    response_model=OrdenReposicionResponse
)
async def registrar_despacho(
    id_orden: str,
    data: DespachoRequest,
    user: UsuarioActual = Depends(require_proveedor)
):
    await AccesoService.verificar_orden(user, id_orden)
    return await service.registrar_despacho(
        id_orden,
        data
    )


# EMPRESA, OPERARIO (su almacén) o PROVEEDOR (enviada a él)
@router.get(
    "/{id_orden}",
    response_model=OrdenReposicionResponse
)
async def obtener_por_id(
    id_orden: str,
    user: UsuarioActual = Depends(get_usuario_activo)
):
    return await AccesoService.verificar_orden(
        user,
        id_orden
    )


@router.put(
    "/{id_orden}",
    response_model=OrdenReposicionResponse
)
async def actualizar(
    id_orden: str,
    data: OrdenReposicionUpdate,
    user: UsuarioActual = Depends(require_operario)
):
    await AccesoService.verificar_orden(user, id_orden)
    return await service.actualizar(id_orden, data)


@router.delete("/{id_orden}")
async def eliminar(
    id_orden: str,
    user: UsuarioActual = Depends(require_operario)
):
    await AccesoService.verificar_orden(user, id_orden)
    return await service.eliminar(id_orden)

app/controllers/producto_controller.py.source:
from typing import List

from fastapi import (
    APIRouter,
    Depends,
    HTTPException,
    status
)

from app.dependencies.dependencies import (
    get_usuario_activo,
    require_empresa_u_operario,
    require_proveedor,
    require_roles
)

from app.dto.auth_dto import (
    UsuarioActual
)

from app.dto.producto_dto import (
    ProductoCreate,
    ProductoUpdate,
    ProductoResponse
)

from app.repositories.inventario_repository import (
    InventarioRepository
)

from app.services.acceso_service import (
    AccesoService
)

from app.services.producto_service import (
    ProductoService
)


# ============================================================
# PRODUCTOS
#
# PROVEEDOR -> crea / edita / borra los suyos; ve solo los suyos.
# OPERARIO  -> lee los de la empresa; edita solo id_rack
#              (rack de referencia, de su almacén).
# EMPRESA   -> solo lectura.
# ============================================================

def _visibles(
    user: UsuarioActual,
    productos: list
) -> list:

    productos = AccesoService.filtrar_empresa(
        user,
        productos
    )

    if user.es_proveedor:

        productos = [
            producto
            for producto in productos
            if producto.get("id_proveedor")
            == user.id_proveedor
        ]

    return productos


router = APIRouter(
    prefix="/productos",
    tags=[
        "Productos"
    ]
)


# ============================================================
# CREAR (PROVEEDOR)
#
# id_proveedor e id_empresa se toman del token.
# Sin rack: el rack de referencia lo asigna el operario.
# ============================================================

@router.post(
    "",
    response_model=ProductoResponse,
    status_code=(
        status.HTTP_201_CREATED
    ),
    summary="Crear producto"
)
async def crear_producto(
    data: ProductoCreate,
    user: UsuarioActual = Depends(
        require_proveedor
    )
):

    data.id_empresa = user.id_empresa

    data.id_proveedor = user.id_proveedor

    data.id_rack = None

    return await (
        ProductoService.crear(
            data
        )
    )


# ============================================================
# OBTENER TODOS (DE LA EMPRESA)
# ============================================================

@router.get(
    "",
    response_model=List[
        ProductoResponse
    ],
    summary="Obtener productos"
)
async def obtener_productos(
    user: UsuarioActual = Depends(
        get_usuario_activo
    )
):

    return _visibles(
        user,
        await (
            ProductoService
            .obtener_todos()
        )
    )


# ============================================================
# REFRIGERADOS
#
# IMPORTANTE:
# antes de /{id_producto}
# ============================================================

@router.get(
    "/refrigerados",
    response_model=List[
        ProductoResponse
    ],
    summary=(
        "Obtener productos refrigerados"
    )
)
async def obtener_productos_refrigerados(
    user: UsuarioActual = Depends(
        get_usuario_activo
    )
):

    return _visibles(
        user,
        await (
            ProductoService
            .obtener_refrigerados()
        )
    )


# ============================================================
# POR ALMACEN
# ============================================================

@router.get(
    "/almacen/{id_almacen}",
    response_model=List[
        ProductoResponse
    ],
    summary=(
        "Obtener productos por almacén"
    )
)
async def obtener_productos_por_almacen(
    id_almacen: str,
    user: UsuarioActual = Depends(
        require_empresa_u_operario
    )
):

    await AccesoService.verificar_almacen(
        user,
        id_almacen
    )

    return await (
        ProductoService
        .obtener_por_almacen(
            id_almacen
        )
    )


# ============================================================
# POR RACK
# ============================================================

@router.get(
    "/rack/{id_rack}",
    response_model=List[
        ProductoResponse
    ],
    summary=(
        "Obtener productos por rack"
    )
)
async def obtener_productos_por_rack(
    id_rack: str,
    user: UsuarioActual = Depends(
        require_empresa_u_operario
    )
):

    await AccesoService.verificar_rack(
        user,
        id_rack
    )

    return await (
        ProductoService
        .obtener_por_rack(
            id_rack
        )
    )


# ============================================================
# POR CATEGORIA
# ============================================================

@router.get(
    "/categoria/{categoria}",
    response_model=List[
        ProductoResponse
    ],
    summary=(
        "Obtener productos por categoría"
    )
)
async def obtener_productos_por_categoria(
    categoria: str,
    user: UsuarioActual = Depends(
        get_usuario_activo
    )
):

    return _visibles(
        user,
        await (
            ProductoService
            .obtener_por_categoria(
                categoria
            )
        )
    )


# ============================================================
# POR ID
#
# DEBE IR DESPUES DE LAS RUTAS ESPECIALES
# ============================================================

@router.get(
    "/{id_producto}",
    response_model=ProductoResponse,
    summary="Obtener producto por ID"
)
async def obtener_producto(
    id_producto: str,
    user: UsuarioActual = Depends(
        get_usuario_activo
    )
):

    await AccesoService.verificar_producto(
        user,
        id_producto
    )

    return await (
        ProductoService
        .obtener_por_id(
            id_producto
        )
    )


# ============================================================
# ACTUALIZAR
#
# PROVEEDOR: sus productos (id_rack se ignora).
# OPERARIO : solo id_rack (rack de referencia).
# ============================================================

@router.put(
    "/{id_producto}",
    response_model=ProductoResponse,
    summary="Actualizar producto"
)
async def actualizar_producto(
    id_producto: str,
    data: ProductoUpdate,
    user: UsuarioActual = Depends(
        require_roles(
            "PROVEEDOR",
            "OPERARIO"
        )
    )
):

    await AccesoService.verificar_producto(
        user,
        id_producto
    )

    if user.es_operario:

        if data.model_fields_set - {"id_rack"}:

            raise HTTPException(
                status_code=403,
                detail=(
                    "El operario solo puede cambiar "
                    "el rack de referencia (id_rack)"
                )
            )

        if data.id_rack:

            await AccesoService.verificar_rack(
                user,
                data.id_rack
            )

    else:

        # El proveedor no gestiona racks: se conserva
        # el rack de referencia actual.
        data = ProductoUpdate(
            **data.model_dump(
                exclude_unset=True,
                exclude={"id_rack"}
            )
        )

    return await (
        ProductoService.actualizar(
            id_producto,
            data
        )
    )


# ============================================================
# ELIMINAR (PROVEEDOR, los suyos)
# ============================================================

@router.delete(
    "/{id_producto}",
    status_code=(
        status.HTTP_200_OK
    ),
    summary="Eliminar producto"
)
async def eliminar_producto(
    id_producto: str,
    user: UsuarioActual = Depends(
        require_proveedor
    )
):

    await AccesoService.verificar_producto(
        user,
        id_producto
    )

    # Un producto con inventario no se borra
    # (dejaría stock huérfano en los racks).
    if await InventarioRepository().obtener_por_producto(
        id_producto
    ):

        raise HTTPException(
            status_code=409,
            detail=(
                "El producto tiene inventarios; "
                "no puede eliminarse"
            )
        )

    return await (
        ProductoService.eliminar(
            id_producto
        )
    )

app/controllers/proveedor_controller.py.source:
from typing import List

from fastapi import APIRouter, Depends, HTTPException, status

from app.dependencies.dependencies import (
    get_usuario_activo,
    require_empresa,
    require_empresa_u_operario
)

from app.dto.auth_dto import (
    ResetPasswordRequest,
    UsuarioActual
)

from app.dto.proveedor_dto import (
    ProveedorCreate,
    ProveedorUpdate,
    ProveedorResponse,
    EstadoProveedor
)
from app.dto.email_verification_dto import (
    EmailVerificationCodeRequest,
    EmailVerificationResponse,
    EmailVerificationSendResponse,
)

from app.services.acceso_service import (
    AccesoService
)

from app.services.cuenta_service import (
    sanitizar_cuenta
)

from app.services.proveedor_service import (
    ProveedorService
)
from app.services.email_verification_service import EmailVerificationService


# ============================================================
# PROVEEDORES
#
# EMPRESA   -> CRUD + cuentas (contraseña temporal).
# OPERARIO  -> solo lectura (elige proveedor al crear
#              una solicitud de reposición).
# PROVEEDOR -> solo puede leer el suyo.
# ============================================================

router = APIRouter(
    prefix="/proveedores",
    tags=["Proveedores"]
)

service = ProveedorService()
email_verification_service = EmailVerificationService()


def _lista(proveedores):
    return [
        sanitizar_cuenta(proveedor)
        for proveedor in proveedores
    ]


@router.post(
    "",
    response_model=ProveedorResponse,
    status_code=status.HTTP_201_CREATED
)
async def crear(
    data: ProveedorCreate,
    user: UsuarioActual = Depends(require_empresa)
):
    data.id_empresa = user.id_empresa
    return sanitizar_cuenta(await service.crear(data))


@router.get(
    "",
    response_model=List[ProveedorResponse]
)
async def obtener_todos(
    user: UsuarioActual = Depends(require_empresa_u_operario)
):
    return _lista(
        await service.obtener_por_empresa(
            user.id_empresa
        )
    )


@router.get(
    "/empresa/{id_empresa}",
    response_model=List[ProveedorResponse]
)
async def obtener_por_empresa(
    id_empresa: str,
    user: UsuarioActual = Depends(require_empresa_u_operario)
):
    AccesoService.verificar_empresa(user, id_empresa)
    return _lista(await service.obtener_por_empresa(id_empresa))


@router.get(
    "/estado/{estado}",
    response_model=List[ProveedorResponse]
)
async def obtener_por_estado(
    estado: EstadoProveedor,
    user: UsuarioActual = Depends(require_empresa_u_operario)
):
    return _lista(
        AccesoService.filtrar_empresa(
            user,
            await service.obtener_por_estado(
                estado.value
            )
        )
    )


@router.get(
    "/{id_proveedor}",
    response_model=ProveedorResponse
)
async def obtener_por_id(
    id_proveedor: str,
    user: UsuarioActual = Depends(get_usuario_activo)
):
    if (
        user.es_proveedor
        and id_proveedor != user.id_proveedor
    ):
        raise HTTPException(
            status_code=403,
            detail="Solo puede consultar su propio proveedor"
        )

    return sanitizar_cuenta(
        await AccesoService.verificar_proveedor(
            user,
            id_proveedor
        )
    )


@router.put(
    "/{id_proveedor}",
    response_model=ProveedorResponse
)
async def actualizar(
    id_proveedor: str,
    data: ProveedorUpdate,
    user: UsuarioActual = Depends(require_empresa)
):
    await AccesoService.verificar_proveedor(user, id_proveedor)
    return sanitizar_cuenta(
        await service.actualizar(
            id_proveedor,
            data
        )
    )


# ============================================================
# RESET PASSWORD (EMPRESA)
#
# Crea o restablece la cuenta del proveedor.
# ============================================================

@router.post(
    "/{id_proveedor}/reset-password",
    response_model=ProveedorResponse
)
async def reset_password(
    id_proveedor: str,
    data: ResetPasswordRequest,
    user: UsuarioActual = Depends(require_empresa)
):
    await AccesoService.verificar_proveedor(user, id_proveedor)
    return sanitizar_cuenta(
        await service.reset_password(
            id_proveedor,
            data.password_temporal,
            str(data.correo) if data.correo else None
        )
    )


@router.delete("/{id_proveedor}")
async def eliminar(
    id_proveedor: str,
    user: UsuarioActual = Depends(require_empresa)
):
    await AccesoService.verificar_proveedor(user, id_proveedor)
    return await service.eliminar(id_proveedor)


@router.post(
    "/{id_proveedor}/correo/enviar-verificacion",
    response_model=EmailVerificationSendResponse,
    summary="Enviar verificación de correo de proveedor",
)
async def send_proveedor_email_verification(
    id_proveedor: str,
    user: UsuarioActual = Depends(require_empresa),
):
    await AccesoService.verificar_proveedor(user, id_proveedor)
    return await email_verification_service.request_entity_verification(
        "proveedor",
        id_proveedor,
    )


@router.post(
    "/{id_proveedor}/correo/verificar",
    response_model=EmailVerificationResponse,
    summary="Verificar correo de proveedor",
)
async def verify_proveedor_email(
    id_proveedor: str,
    data: EmailVerificationCodeRequest,
    user: UsuarioActual = Depends(require_empresa),
):
    await AccesoService.verificar_proveedor(user, id_proveedor)
    return await email_verification_service.verify_entity_code(
        "proveedor",
        id_proveedor,
        data.codigo,
    )

