    "/{id_zona}",
    response_model=ZonaResponse
)
async def obtener_zona(
    id_zona: str,
    user: UsuarioActual = Depends(
        require_empresa_u_operario
    )
):

    await AccesoService.verificar_zona(
        user,
        id_zona
    )

    return await (
        ZonaService.obtener_por_id(
            id_zona
        )
    )


# ============================================================
# ACTUALIZAR (EMPRESA)
# ============================================================

@router.put(
    "/{id_zona}",
    response_model=ZonaResponse
)
