from datetime import (
    datetime,
    timezone
)

from uuid import uuid4

from typing import (
    Optional,
    Dict,
    Any,
    List
)

from app.database.mongodb import (
    get_database
)


class MovimientoRepository:

    COLLECTION_NAME = "movimientos"


    # ============================================================
    # COLLECTION
    # ============================================================

    def collection(self):

        database = get_database()

        return database[
            self.COLLECTION_NAME
        ]


    # ============================================================
    # CREAR
    # ============================================================

    async def crear(
        self,
        data: Dict[str, Any]
    ) -> Dict[str, Any]:

        documento = dict(data)

        documento[
            "id_movimiento"
        ] = str(
            uuid4()
        )

        # Si el servicio no envía fecha_hora,
        # utilizamos la fecha actual.
        if not documento.get(
            "fecha_hora"
        ):

            documento[
                "fecha_hora"
            ] = datetime.now(
                timezone.utc
            )

        await self.collection().insert_one(
            documento
        )

        return await self.obtener_por_id(
            documento[
                "id_movimiento"
            ]
        )


    # ============================================================
    # OBTENER TODOS
    # ============================================================

    async def obtener_todos(
        self
    ) -> List[Dict[str, Any]]:

        cursor = (
            self.collection()
            .find(
                {},
                {
                    "_id": 0
                }
            )
            .sort(
                "fecha_hora",
                -1
            )
        )

        return await cursor.to_list(
            length=None
        )


    # ============================================================
    # OBTENER POR ID
    # ============================================================

