    async def eliminar(
        self,
        id_movimiento: str
    ) -> bool:
        resultado = await self.collection().delete_one(
            {
                "id_movimiento": id_movimiento
            }
        )
        return resultado.deleted_count > 0


    # ============================================================
    # OBTENER POR INVENTARIO
    # ============================================================

    async def obtener_por_inventario(
        self,
        id_inventario: str
    ) -> List[Dict[str, Any]]:

