    ) -> List[Dict[str, Any]]:

        cursor = (
            self.collection()
            .find(
                {
                    "id_producto":
                        id_producto
                },
                {
                    "_id": 0
                }
            )
            .sort(
                "fecha_hora",
                -1
            )
        )

        return await cursor.to_list(
            length=None
        )


    # ============================================================
    # OBTENER POR RACK
    # ============================================================

    async def obtener_por_rack(
        self,
        id_rack: str
    ) -> List[Dict[str, Any]]:

        cursor = (
            self.collection()
            .find(
                {
                    "id_rack":
                        id_rack
                },
                {
                    "_id": 0
                }
            )
            .sort(
                "fecha_hora",
                -1
            )
