                }
            )
            .sort(
                "fecha_creacion",
                -1
            )
        )

        return await cursor.to_list(
            length=None
        )

    # ============================================================
    # BUSCAR RECOMENDACION PENDIENTE
    # ============================================================

    async def buscar_pendiente(
        self,
        id_inventario: str,
        tipo_recomendacion: str
    ) -> Optional[dict]:

        return await self.collection().find_one(
            {
                "id_inventario":
                    id_inventario,

                "tipo_recomendacion":
                    tipo_recomendacion,

                "estado": {
                    "$in": [
                        "PENDIENTE",
                        "ACEPTADA"
                    ]
                }
            },
            {
                "_id": 0
            }
        )

    # ============================================================
    # ACTUALIZAR
    # ============================================================

    async def actualizar(
        self,
        id_recomendacion: str,
        datos: dict
    ) -> Optional[dict]:

        resultado = (
            await self.collection().update_one(
                {
                    "id_recomendacion":
                        id_recomendacion
                },
                {
                    "$set":
                        datos
                }
            )
        )

        if resultado.matched_count == 0:

            return None

        return await self.obtener_por_id(
            id_recomendacion
        )

    # ============================================================
    # ELIMINAR
    # ============================================================

    async def eliminar(
        self,
        id_recomendacion: str
    ) -> bool:

        resultado = (
            await self.collection().delete_one(
                {
                    "id_recomendacion":
                        id_recomendacion
                }
            )
        )

        return (
            resultado.deleted_count > 0
        )

