from fastapi import HTTPException

from app.database.mongodb import get_database

from app.dto.detalle_reposicion_dto import (
    DetalleReposicionCreate,
    DetalleReposicionUpdate
)

from app.repositories.detalle_reposicion_repository import (
    DetalleReposicionRepository
)

from app.repositories.orden_reposicion_repository import (
    OrdenReposicionRepository
)


class DetalleReposicionService:

    def __init__(self):
        self.repository = DetalleReposicionRepository()
        self.orden_repository = OrdenReposicionRepository()

    async def crear(
        self,
        id_orden: str,
        data: DetalleReposicionCreate
    ):

        orden = await self.orden_repository.obtener_por_id(
            id_orden
        )

        if not orden:
            raise HTTPException(
                status_code=404,
                detail="Orden no encontrada"
            )

        if orden["estado"] not in ("PENDIENTE", "OBSERVADA"):
            raise HTTPException(
                status_code=409,
                detail=(
                    "Solo pueden agregarse productos "
                    "a una orden pendiente"
                )
            )

        db = get_database()

        producto = await db["productos"].find_one(
            {
                "$or": [
                    {"id_producto": data.id_producto},
                    {"id": data.id_producto}
                ]
            }
        )

        if not producto:
            raise HTTPException(
                status_code=404,
                detail="Producto no encontrado"
            )

        if (
            producto.get("id_empresa")
            and producto.get("id_empresa")
            != orden["id_empresa"]
        ):
            raise HTTPException(
                status_code=400,
                detail=(
                    "El producto no pertenece "
                    "a la empresa de la orden"
                )
            )

        existente = (
            await self.repository.obtener_producto_en_orden(
                id_orden,
                data.id_producto
            )
        )

        if existente:
            raise HTTPException(
                status_code=409,
                detail=(
                    "El producto ya existe "
                    "en esta orden"
                )
            )

        documento = data.model_dump()

        documento["id_orden_reposicion"] = id_orden

        return await self.repository.crear(documento)

    async def obtener_por_orden(self, id_orden):

        return await self.repository.obtener_por_orden(
            id_orden
        )

    async def obtener_por_id(self, id_detalle):

        detalle = await self.repository.obtener_por_id(
            id_detalle
        )

        if not detalle:
            raise HTTPException(
                status_code=404,
                detail="Detalle no encontrado"
            )

        return detalle

    async def actualizar(
        self,
        id_detalle,
        data: DetalleReposicionUpdate
    ):

        detalle = await self.obtener_por_id(id_detalle)

        orden = await self.orden_repository.obtener_por_id(
            detalle["id_orden_reposicion"]
        )

        if orden["estado"] not in ("PENDIENTE", "OBSERVADA"):
            raise HTTPException(
                status_code=409,
                detail=(
                    "El detalle ya no puede modificarse"
                )
            )

        cambios = data.model_dump(
            exclude_unset=True
        )

        return await self.repository.actualizar(
            id_detalle,
            cambios
        )

    async def eliminar(self, id_detalle):

        detalle = await self.obtener_por_id(id_detalle)

        orden = await self.orden_repository.obtener_por_id(
            detalle["id_orden_reposicion"]
        )

        if orden["estado"] not in ("PENDIENTE", "OBSERVADA"):
            raise HTTPException(
                status_code=409,
                detail="El detalle ya no puede eliminarse"
            )

        await self.repository.eliminar(id_detalle)

        return {
            "mensaje":
                "Detalle eliminado correctamente"
        }

app/services/email_verification_service..source:
from __future__ import annotations

import hashlib
import secrets
from datetime import datetime, timedelta, timezone
from typing import Any, Callable

from app.config.settings import settings
from app.database.mongodb import get_database


class EmailVerificationService:
    COLLECTION_NAME = "email_verifications"
    ENTITY_COLLECTIONS = {
        "empresa": "empresas",
        "operario": "operarios",
        "proveedor": "proveedores",
    }

    def __init__(
        self,
        database_provider: Callable[[], Any] | None = None,
        sender: Callable[..., Any] | None = None,
    ):
        self.database_provider = database_provider or get_database
        self.sender = sender or self._send_email

    def database(self):
        return self.database_provider()

    @staticmethod
    def normalize_email(email: str | None) -> str:
        return str(email or "").strip().lower()

    @staticmethod
    def generate_code(length: int = 6) -> str:
        return "".join(
            secrets.choice("0123456789")
            for _ in range(length)
        )

    @staticmethod
    def hash_code(code: str) -> str:
        return hashlib.sha256(code.encode("utf-8")).hexdigest()

    @staticmethod
    def _as_utc(value: datetime | None) -> datetime | None:
        if not isinstance(value, datetime):
            return None
        if value.tzinfo is None:
            return value.replace(tzinfo=timezone.utc)
        return value.astimezone(timezone.utc)

    async def _get_entity_record(self, entity_type: str, entity_id: str):
        collection_name = self.ENTITY_COLLECTIONS.get(entity_type.lower())
        if not collection_name:
            return None
        collection = self.database()[collection_name]
        return await collection.find_one(
            {
                "$or": [
                    {"id_empresa": entity_id},
                    {"id_operario": entity_id},
                    {"id_proveedor": entity_id},
                    {"id": entity_id},
                ]
            },
            {"_id": 0},
        )

    async def _upsert_entity_email_status(
        self,
        entity_type: str,
        entity_id: str,
        email: str,
        *,
        verified: bool,
    ):
        entity = await self._get_entity_record(entity_type, entity_id)
        if entity is None:
            return None

        collection_name = self.ENTITY_COLLECTIONS.get(entity_type.lower())
        if not collection_name:
            return None

        collection = self.database()[collection_name]
        payload = {
            "correo": email,
            "correo_verificado": verified,
        }
        if verified:
            payload["fecha_verificacion_correo"] = datetime.now(timezone.utc)
        else:
            payload["fecha_verificacion_correo"] = None

        await collection.update_one(
            {
                "$or": [
                    {"id_empresa": entity_id},
                    {"id_operario": entity_id},
                    {"id_proveedor": entity_id},
                    {"id": entity_id},
                ]
            },
            {"$set": payload},
        )

        return await collection.find_one(
            {
                "$or": [
                    {"id_empresa": entity_id},
                    {"id_operario": entity_id},
                    {"id_proveedor": entity_id},
                    {"id": entity_id},
                ]
            },
            {"_id": 0},
        )

    async def request_entity_verification(
        self,
        entity_type: str,
        entity_id: str,
    ) -> dict[str, Any]:
        entity = await self._get_entity_record(entity_type, entity_id)
        if not entity:
            return {"status": "ERROR", "reason": "Entidad no encontrada"}

        result = await self.request_verification(
            entity_type,
            entity_id,
            entity.get("correo"),
        )
        verification = result.get("verification") or {}
        return {
            "status": result.get("status"),
            "email": result.get("email") or verification.get("email"),
            "remaining_seconds": result.get("remaining_seconds"),
            "reason": result.get("reason"),
        }

    async def verify_entity_code(
        self,
        entity_type: str,
        entity_id: str,
        code: str,
    ) -> dict[str, Any]:
        entity = await self._get_entity_record(entity_type, entity_id)
        if not entity:
            return {
                "verified": False,
                "status": "NOT_FOUND",
            }

        result = await self.verify_code(
            entity_type,
            entity_id,
            entity.get("correo"),
            code,
        )
        updated_entity = result.get("entity") or {}
        return {
            "verified": bool(result.get("verified")),
            "status": result.get("status"),
            "email": updated_entity.get("correo") or entity.get("correo"),
            "attempts": result.get("attempts"),
            "remaining_attempts": result.get("remaining_attempts"),
        }

    async def request_verification(
        self,
        entity_type: str,
        entity_id: str,
        email: str,
        *,
        expires_minutes: int | None = None,
        max_attempts: int | None = None,
        cooldown_seconds: int | None = None,
    ) -> dict[str, Any]:
        normalized_email = self.normalize_email(email)
        if not normalized_email:
            return {"status": "ERROR", "reason": "Correo requerido"}

        expires_minutes = expires_minutes or settings.email_verification_ttl_minutes
        max_attempts = max_attempts or settings.email_verification_max_attempts
        cooldown_seconds = cooldown_seconds or settings.email_verification_cooldown_seconds

        entity = await self._get_entity_record(entity_type, entity_id)
        if not entity:
            return {"status": "ERROR", "reason": "Entidad no encontrada"}

        collection = self.database()[self.COLLECTION_NAME]
        existing = await collection.find_one(
            {
                "entity_type": entity_type.lower(),
                "entity_id": entity_id,
                "email": normalized_email,
            },
            {"_id": 0},
        )

        if existing:
            now = datetime.now(timezone.utc)
            expires_at = self._as_utc(existing.get("expires_at"))
            if expires_at is not None and expires_at > now:
                cooldown_until = self._as_utc(existing.get("cooldown_until"))
                if cooldown_until is not None and cooldown_until > now:
                    return {
                        "status": "COOLDOWN",
                        "remaining_seconds": max(
                            0,
                            int((cooldown_until - now).total_seconds()),
                        ),
                        "email": normalized_email,
                    }

        code = self.generate_code()
        now = datetime.now(timezone.utc)
        verification = {
            "entity_type": entity_type.lower(),
            "entity_id": entity_id,
            "email": normalized_email,
            "code_hash": self.hash_code(code),
            "expires_at": now + timedelta(minutes=expires_minutes),
            "attempts": 0,
            "max_attempts": max_attempts,
            "cooldown_until": now + timedelta(seconds=cooldown_seconds),
            "used": False,
            "status": "PENDING",
            "created_at": now,
            "updated_at": now,
        }

        await collection.update_one(
            {
                "entity_type": entity_type.lower(),
                "entity_id": entity_id,
                "email": normalized_email,
            },
            {"$set": verification},
            upsert=True,
        )

        subject = f"[PsiTwin] Verificación de email - {entity_type.title()}"
        body = "\n".join(
            [
                "PsiTwin verifica tu dirección de correo.",
                f"Entidad: {entity_type.title()}",
                f"Correo: {normalized_email}",
                "Tu código temporal es:",
                code,
                f"Este código expira en {expires_minutes} minutos y solo puede usarse una vez.",
            ]
        )

        try:
            self.sender(normalized_email, subject, body)
        except Exception:
            return {
                "status": "ERROR",
                "reason": "No se pudo enviar el correo de verificación",
                "email": normalized_email,
            }
        return {
            "status": "SENT",
            "verification": {
                "entity_type": entity_type.lower(),
                "entity_id": entity_id,
                "email": normalized_email,
                "expires_at": verification["expires_at"],
                "max_attempts": max_attempts,
                "cooldown_seconds": cooldown_seconds,
            },
        }

    async def verify_code(
        self,
        entity_type: str,
        entity_id: str,
        email: str,
        code: str,
    ) -> dict[str, Any]:
        normalized_email = self.normalize_email(email)
        collection = self.database()[self.COLLECTION_NAME]
        record = await collection.find_one(
            {
                "entity_type": entity_type.lower(),
                "entity_id": entity_id,
                "email": normalized_email,
            },
            {"_id": 0},
        )

        if not record:
            return {"verified": False, "status": "NOT_FOUND"}

        if record.get("used"):
            return {"verified": False, "status": "REUSED"}

        now = datetime.now(timezone.utc)
        expires_at = self._as_utc(record.get("expires_at"))
        if expires_at is not None and expires_at < now:
            await collection.update_one(
                {
                    "entity_type": entity_type.lower(),
                    "entity_id": entity_id,
                    "email": normalized_email,
                },
                {"$set": {"used": True, "status": "EXPIRED", "updated_at": now}},
            )
            return {"verified": False, "status": "EXPIRED"}

        attempts = int(record.get("attempts", 0))
        max_attempts = int(record.get("max_attempts", 5))
        if attempts >= max_attempts:
            await collection.update_one(
                {
                    "entity_type": entity_type.lower(),
                    "entity_id": entity_id,
                    "email": normalized_email,
                },
                {"$set": {"used": True, "status": "LOCKED", "updated_at": now}},
            )
            return {
                "verified": False,
                "status": "MAX_ATTEMPTS",
                "attempts": attempts,
            }

        if record.get("code_hash") != self.hash_code(str(code)):
            attempts += 1
            await collection.update_one(
                {
                    "entity_type": entity_type.lower(),
                    "entity_id": entity_id,
                    "email": normalized_email,
                },
                {
                    "$set": {
                        "attempts": attempts,
                        "status": "INVALID_CODE",
                        "updated_at": now,
                    }
                },
            )
            return {
                "verified": False,
                "status": "INVALID_CODE",
                "attempts": attempts,
                "remaining_attempts": max_attempts - attempts,
            }

        await collection.update_one(
            {
                "entity_type": entity_type.lower(),
                "entity_id": entity_id,
                "email": normalized_email,
            },
            {"$set": {"used": True, "status": "VERIFIED", "updated_at": now}},
        )

        updated_entity = await self._upsert_entity_email_status(
            entity_type,
            entity_id,
            normalized_email,
            verified=True,
        )

        return {
            "verified": True,
            "status": "VERIFIED",
            "entity": updated_entity,
        }

    async def invalidate_on_email_change(
        self,
        entity_type: str,
        entity_id: str,
        old_email: str,
        new_email: str,
    ):
        old_email_norm = self.normalize_email(old_email)
        new_email_norm = self.normalize_email(new_email)
        if not old_email_norm or old_email_norm == new_email_norm:
            return {"correo_verificado": False, "correo": new_email_norm}

        collection_name = self.ENTITY_COLLECTIONS.get(entity_type.lower())
        if not collection_name:
            return {"correo_verificado": False, "correo": new_email_norm}

        collection = self.database()[collection_name]
        record = await collection.find_one(
            {
                "$or": [
                    {"id_empresa": entity_id},
                    {"id_operario": entity_id},
                    {"id_proveedor": entity_id},
                    {"id": entity_id},
                ]
            },
            {"_id": 0},
        )
        if record is None:
            return {"correo_verificado": False, "correo": new_email_norm}

        updated = await collection.update_one(
            {
                "$or": [
                    {"id_empresa": entity_id},
                    {"id_operario": entity_id},
                    {"id_proveedor": entity_id},
                    {"id": entity_id},
                ]
            },
            {
                "$set": {
                    "correo": new_email_norm,
                    "correo_verificado": False,
                    "fecha_verificacion_correo": None,
                }
            },
        )

        validation_collection = self.database()[self.COLLECTION_NAME]
        await validation_collection.update_one(
            {
                "entity_type": entity_type.lower(),
                "entity_id": entity_id,
                "email": old_email_norm,
            },
            {
                "$set": {
                    "used": True,
                    "status": "INVALIDATED_BY_EMAIL_CHANGE",
                    "updated_at": datetime.now(timezone.utc),
                }
            },
        )

        matched = getattr(updated, "matched_count", 1 if updated is not None else 0)
        if matched == 0:
            return {"correo_verificado": False, "correo": new_email_norm}

        return await collection.find_one(
            {
                "$or": [
                    {"id_empresa": entity_id},
                    {"id_operario": entity_id},
                    {"id_proveedor": entity_id},
                    {"id": entity_id},
                ]
            },
            {"_id": 0},
        )

    def _send_email(self, recipient: str, subject: str, body: str):
        if settings.email_enabled and all(
            (
                settings.smtp_host,
                settings.smtp_user,
                settings.smtp_password,
                settings.smtp_from or settings.smtp_user,
            )
        ):
            from email.message import EmailMessage
            import smtplib

            message = EmailMessage()
            message["From"] = settings.smtp_from or settings.smtp_user
            message["To"] = recipient
            message["Subject"] = subject
            message.set_content(body)
            with smtplib.SMTP(settings.smtp_host, settings.smtp_port, timeout=20) as server:
                if settings.smtp_use_tls:
                    server.starttls()
                server.login(settings.smtp_user, settings.smtp_password)
                server.send_message(message)
        return {"status": "MOCKED", "recipient": recipient, "subject": subject}

app/services/empresa_service.py.source:
from datetime import (
    datetime,
    timedelta,
    timezone
)

from uuid import uuid4

from typing import (
    Dict,
    Any
)

import bcrypt
import jwt

from jwt import (
    ExpiredSignatureError,
    InvalidTokenError
)

from fastapi import (
    HTTPException,
    status
)

from app.config.settings import (
    settings
)

from app.dto.empresa_dto import (
    EmpresaRegisterRequest,
    EmpresaLoginRequest,
    EmpresaUpdateRequest,
    EmpresaChangePasswordRequest,
    EmpresaDeleteRequest
)

from app.repositories import (
    empresa_repository
)

from app.services.cuenta_service import (
    validar_correo_disponible
)

from app.utils import (
    security
)


# ============================================================
# PASSWORD
# ============================================================

def hash_password(
    password: str
) -> str:

    hashed = bcrypt.hashpw(
        password.encode(
            "utf-8"
        ),
        bcrypt.gensalt()
    )

    return hashed.decode(
        "utf-8"
    )


def verify_password(
    plain_password: str,
    hashed_password: str
) -> bool:

    try:

        return bcrypt.checkpw(
            plain_password.encode(
                "utf-8"
            ),
            hashed_password.encode(
                "utf-8"
            )
        )

    except Exception:

        return False


# ============================================================
# SANITIZAR
# ============================================================

def sanitize_empresa(
    empresa: Dict[str, Any]
) -> Dict[str, Any]:

    safe_empresa = dict(
        empresa
    )

    safe_empresa.pop(
        "password",
        None
    )

    safe_empresa.pop(
        "_id",
        None
    )

    return safe_empresa


# ============================================================
# JWT
# ============================================================

def create_access_token(
    id_empresa: str
) -> str:

    # Delegado a app.utils.security: el token
    # incluye ahora rol = EMPRESA e id_empresa.

    return security.create_access_token(
        sub=id_empresa,
        rol=security.ROL_EMPRESA,
        id_empresa=id_empresa
    )


def decode_access_token(
    token: str
) -> str:

    try:

        payload = jwt.decode(
            token,
            settings.secret_key,
            algorithms=[
                settings.algorithm
            ]
        )

        id_empresa = payload.get(
            "sub"
        )

        token_type = payload.get(
            "type"
        )

        if (
            not id_empresa
            or
            token_type != "empresa"
        ):

            raise HTTPException(
                status_code=(
                    status.HTTP_401_UNAUTHORIZED
                ),
                detail="Token inválido",
                headers={
                    "WWW-Authenticate":
                        "Bearer"
                }
            )

        return id_empresa

    except ExpiredSignatureError:

        raise HTTPException(
            status_code=(
                status.HTTP_401_UNAUTHORIZED
            ),
            detail="Token expirado",
            headers={
                "WWW-Authenticate":
                    "Bearer"
            }
        )

    except InvalidTokenError:

        raise HTTPException(
            status_code=(
                status.HTTP_401_UNAUTHORIZED
            ),
            detail="Token inválido",
            headers={
                "WWW-Authenticate":
                    "Bearer"
            }
        )


# ============================================================
# REGISTER
# ============================================================

async def register_empresa(
    data: EmpresaRegisterRequest
) -> Dict[str, Any]:

    correo = (
        str(data.correo)
        .lower()
        .strip()
    )

    ruc = (
        data.ruc
        .strip()
    )

    existing_email = (
        await empresa_repository
        .find_by_email(
            correo
        )
    )

    if existing_email:

        raise HTTPException(
            status_code=(
                status.HTTP_409_CONFLICT
            ),
            detail=(
                "Ya existe una empresa "
                "registrada con ese correo"
            )
        )

    # Único entre empresas, operarios y proveedores
    await validar_correo_disponible(
        correo
    )

    existing_ruc = (
        await empresa_repository
        .find_by_ruc(
            ruc
        )
    )

    if existing_ruc:

        raise HTTPException(
            status_code=(
                status.HTTP_409_CONFLICT
            ),
            detail=(
                "Ya existe una empresa "
                "registrada con ese RUC"
            )
        )

    now = datetime.now(
        timezone.utc
    ).isoformat()

    empresa = {

        "id_empresa":
            str(
                uuid4()
            ),

        "nombre":
            data.nombre.strip(),

        "ruc":
            ruc,

        "sector":
            data.sector.strip(),

        "correo":
            correo,

        "correo_verificado":
            False,

        "fecha_verificacion_correo":
            None,

        "telefono":
            data.telefono.strip(),

        "password":
            hash_password(
                data.password
            ),

        "fecha_creacion":
            now,

        "fecha_actualizacion":
            now
    }

    created = (
        await empresa_repository
        .create_empresa(
            empresa
        )
    )

    return sanitize_empresa(
        created
    )


# ============================================================
# LOGIN
# ============================================================

async def login_empresa(
    data: EmpresaLoginRequest
) -> Dict[str, Any]:

    correo = (
        str(data.correo)
        .lower()
        .strip()
    )

    empresa = (
        await empresa_repository
        .find_by_email(
            correo
        )
    )

    if not empresa:

        raise HTTPException(
            status_code=(
                status.HTTP_401_UNAUTHORIZED
            ),
            detail=(
                "Correo o contraseña incorrectos"
            )
        )

    stored_password = (
        empresa.get(
            "password"
        )
    )

    if (
        not stored_password
        or
        not verify_password(
            data.password,
            stored_password
        )
    ):

        raise HTTPException(
            status_code=(
                status.HTTP_401_UNAUTHORIZED
            ),
            detail=(
                "Correo o contraseña incorrectos"
            )
        )

    token = create_access_token(
        empresa[
            "id_empresa"
        ]
    )

    return {

        "access_token":
            token,

        "token_type":
            "bearer",

        "empresa":
            sanitize_empresa(
                empresa
            )
    }


# ============================================================
# GET PERFIL
# ============================================================

async def get_empresa_profile(
    id_empresa: str
) -> Dict[str, Any]:

    empresa = (
        await empresa_repository
        .find_by_id(
            id_empresa
        )
    )

    if not empresa:

        raise HTTPException(
            status_code=(
                status.HTTP_404_NOT_FOUND
            ),
            detail=(
                "Empresa no encontrada"
            )
        )

    return sanitize_empresa(
        empresa
    )


# ============================================================
# UPDATE PERFIL
# ============================================================

async def update_empresa_profile(
    id_empresa: str,
    data: EmpresaUpdateRequest
) -> Dict[str, Any]:

    current = (
        await empresa_repository
        .find_by_id(
            id_empresa
        )
    )

    if not current:

        raise HTTPException(
            status_code=(
                status.HTTP_404_NOT_FOUND
            ),
            detail=(
                "Empresa no encontrada"
            )
        )

    update_data = (
        data.model_dump(
            exclude_unset=True
        )
    )

    if not update_data:

        return sanitize_empresa(
            current
        )

    # ========================================================
    # CORREO
    # ========================================================

    if "correo" in update_data:

        correo = (
            str(
                update_data[
                    "correo"
                ]
            )
            .lower()
            .strip()
        )

        existing = (
            await empresa_repository
            .find_by_email(
                correo
            )
        )

        if (
            existing
            and
            existing[
                "id_empresa"
            ]
            !=
            id_empresa
        ):

            raise HTTPException(
                status_code=(
                    status.HTTP_409_CONFLICT
                ),
                detail=(
                    "El correo ya está registrado"
                )
            )

        await validar_correo_disponible(
            correo,
            id_empresa
        )

        if current.get("correo") and current.get("correo").lower() != correo:
            update_data["correo_verificado"] = False
            update_data["fecha_verificacion_correo"] = None

        update_data[
            "correo"
        ] = correo


    # ========================================================
    # RUC
    # ========================================================

    if "ruc" in update_data:

        ruc = (
            update_data[
                "ruc"
            ]
            .strip()
        )

        existing = (
            await empresa_repository
            .find_by_ruc(
                ruc
            )
        )

        if (
            existing
            and
            existing[
                "id_empresa"
            ]
            !=
            id_empresa
        ):

            raise HTTPException(
                status_code=(
                    status.HTTP_409_CONFLICT
                ),
                detail=(
                    "El RUC ya está registrado"
                )
            )

        update_data[
            "ruc"
        ] = ruc


    # ========================================================
    # NORMALIZAR TEXTOS
    # ========================================================

    for field in [
        "nombre",
        "sector",
        "telefono"
    ]:

        if (
            field in update_data
            and
            update_data[field]
        ):

            update_data[
                field
            ] = (
                update_data[
                    field
                ]
                .strip()
            )


    updated = (
        await empresa_repository
        .update_empresa(
            id_empresa,
            update_data
        )
    )

    if not updated:

        raise HTTPException(
            status_code=(
                status.HTTP_404_NOT_FOUND
            ),
            detail=(
                "Empresa no encontrada"
            )
        )

    return sanitize_empresa(
        updated
    )


# ============================================================
# PATCH PASSWORD
# ============================================================

async def change_empresa_password(
    id_empresa: str,
    data: EmpresaChangePasswordRequest
) -> Dict[str, str]:

    empresa = (
        await empresa_repository
        .find_by_id(
            id_empresa
        )
    )

    if not empresa:

        raise HTTPException(
            status_code=(
                status.HTTP_404_NOT_FOUND
            ),
            detail=(
                "Empresa no encontrada"
            )
        )

    current_hash = (
        empresa.get(
            "password"
        )
    )

    if (
        not current_hash
        or
        not verify_password(
            data.password_actual,
            current_hash
        )
    ):

        raise HTTPException(
            status_code=(
                status.HTTP_400_BAD_REQUEST
            ),
            detail=(
                "La contraseña actual "
                "es incorrecta"
            )
        )

    if (
        data.password_actual
        ==
        data.password_nueva
    ):

        raise HTTPException(
            status_code=(
                status.HTTP_400_BAD_REQUEST
            ),
            detail=(
                "La nueva contraseña debe "
                "ser diferente a la actual"
            )
        )

    new_hash = hash_password(
        data.password_nueva
    )

    success = (
        await empresa_repository
        .update_password(
            id_empresa,
            new_hash
        )
    )

    if not success:

        raise HTTPException(
            status_code=(
                status.HTTP_500_INTERNAL_SERVER_ERROR
            ),
            detail=(
                "No se pudo actualizar "
                "la contraseña"
            )
        )

    return {
        "mensaje":
            "Contraseña actualizada correctamente"
    }


# ============================================================
# DELETE EMPRESA
# ============================================================

async def delete_empresa_profile(
    id_empresa: str,
    data: EmpresaDeleteRequest
) -> Dict[str, str]:

    empresa = (
        await empresa_repository
        .find_by_id(
            id_empresa
        )
    )

    if not empresa:

        raise HTTPException(
            status_code=(
                status.HTTP_404_NOT_FOUND
            ),
            detail=(
                "Empresa no encontrada"
            )
        )

    stored_password = (
        empresa.get(
            "password"
        )
    )

    if (
        not stored_password
        or
        not verify_password(
            data.password,
            stored_password
        )
    ):

        raise HTTPException(
            status_code=(
                status.HTTP_401_UNAUTHORIZED
            ),
            detail=(
                "Contraseña incorrecta"
            )
        )

    deleted = (
        await empresa_repository
        .delete_empresa(
            id_empresa
        )
    )

    if not deleted:

        raise HTTPException(
            status_code=(
                status.HTTP_500_INTERNAL_SERVER_ERROR
            ),
            detail=(
                "No se pudo eliminar "
                "la empresa"
            )
        )

    return {
        "mensaje":
            "Empresa eliminada correctamente"
    }

