from fastapi import HTTPException, status

from app.dto.proveedor_dto import (
    ProveedorCreate,
    ProveedorUpdate
)

from app.repositories.proveedor_repository import (
    ProveedorRepository
)

from app.repositories.empresa_repository import (
    EmpresaRepository
)


from app.services.cuenta_service import (
    validar_correo_disponible
)

from app.utils.security import (
    hash_password
)


class ProveedorService:

    def __init__(self):
        self.repository = ProveedorRepository()

    async def crear(self, data: ProveedorCreate):

        empresa = await EmpresaRepository.obtener_por_id(
            data.id_empresa
        )

        if not empresa:
            raise HTTPException(
                status_code=status.HTTP_404_NOT_FOUND,
                detail="Empresa no encontrada"
            )

        existente = await self.repository.obtener_por_ruc(
            data.ruc
        )

        if existente:
            raise HTTPException(
                status_code=status.HTTP_409_CONFLICT,
                detail="Ya existe un proveedor con ese RUC"
            )

        documento = data.model_dump()

        # ----------------------------------------------------
        # CUENTA DE ACCESO (opcional)
        # ----------------------------------------------------

        password_temporal = documento.pop(
            "password_temporal",
            None
        )

        if password_temporal:

            if not data.correo:
                raise HTTPException(
                    status_code=422,
                    detail=(
                        "El correo es obligatorio para "
                        "crear la cuenta del proveedor"
                    )
                )

            await validar_correo_disponible(
                str(data.correo)
            )

            documento["password_hash"] = hash_password(
                password_temporal
            )
            documento["debe_cambiar_password"] = True

        documento["correo"] = str(documento.get("correo") or "").strip().lower() if documento.get("correo") else None
        documento["estado"] = data.estado.value
        documento["correo_verificado"] = False
        documento["fecha_verificacion_correo"] = None

        return await self.repository.crear(documento)

    async def obtener_todos(self):
        return await self.repository.obtener_todos()

    async def obtener_por_id(self, id_proveedor: str):

        proveedor = await self.repository.obtener_por_id(
            id_proveedor
        )

        if not proveedor:
            raise HTTPException(
                status_code=status.HTTP_404_NOT_FOUND,
                detail="Proveedor no encontrado"
            )

        return proveedor

    async def obtener_por_empresa(self, id_empresa: str):

        return await self.repository.obtener_por_empresa(
            id_empresa
        )

    async def obtener_por_estado(self, estado: str):

        return await self.repository.obtener_por_estado(
            estado
        )

    async def actualizar(
        self,
        id_proveedor: str,
        data: ProveedorUpdate
    ):

        proveedor = await self.obtener_por_id(id_proveedor)

        cambios = data.model_dump(
            exclude_unset=True
        )

        if "correo" in cambios and cambios["correo"] is not None:
            cambios["correo"] = str(cambios["correo"]).strip().lower()
            if proveedor.get("password_hash"):
                await validar_correo_disponible(
                    cambios["correo"],
                    id_proveedor
                )
            if proveedor.get("correo") and proveedor.get("correo").lower() != cambios["correo"]:
                cambios["correo_verificado"] = False
                cambios["fecha_verificacion_correo"] = None

        if "estado" in cambios:
            cambios["estado"] = cambios["estado"].value

        return await self.repository.actualizar(
            id_proveedor,
            cambios
        )

    # ========================================================
    # RESET PASSWORD (EMPRESA)
    #
    # Da o restablece la cuenta del proveedor.
    # ========================================================

    async def reset_password(
        self,
        id_proveedor: str,
        password_temporal: str,
        correo: str | None = None
    ):

        proveedor = await self.obtener_por_id(id_proveedor)

        correo = correo or proveedor.get("correo")

        if not correo:
            raise HTTPException(
                status_code=409,
                detail=(
                    "El proveedor no tiene correo. "
                    "Envíe 'correo' en el body"
                )
            )

        cambios = {
            "correo": await validar_correo_disponible(
                correo,
                id_proveedor
            ),
            "password_hash": hash_password(
                password_temporal
            ),
            "debe_cambiar_password": True
        }

        if cambios["correo"] != (proveedor.get("correo") or "").lower():
            cambios["correo_verificado"] = False
            cambios["fecha_verificacion_correo"] = None

        return await self.repository.actualizar(
            id_proveedor,
            cambios
        )

    async def eliminar(self, id_proveedor: str):

        await self.obtener_por_id(id_proveedor)

        eliminado = await self.repository.eliminar(
            id_proveedor
        )

        if not eliminado:
            raise HTTPException(
                status_code=500,
                detail="No se pudo eliminar el proveedor"
            )

        return {
            "mensaje": "Proveedor eliminado correctamente"
        }

app/services/rack_service.py.source:
from datetime import (
    datetime,
    timezone
)

from typing import (
    Any,
    Dict,
    List,
    Optional,
    Set
)

from uuid import uuid4

from fastapi import HTTPException

from app.database.mongodb import (
    get_database
)

from app.dto.rack_dto import (
    RackCreate,
    RackUpdate
)

from app.repositories.rack_repository import (
    RackRepository
)

from app.repositories.zona_repository import (
    ZonaRepository
)

from app.repositories.inventario_repository import (
    InventarioRepository
)


def _id_rack(
    rack: Dict[str, Any]
) -> Optional[str]:

    return (
        rack.get("id_rack")
        or
        rack.get("id")
    )


def _kg(
    valor: float
) -> str:

    return f"{round(float(valor), 2):g}"


class RackService:

    def __init__(self):
        self.repository = RackRepository()
        self.zona_repository = ZonaRepository()


    # ============================================================
    # CARGA / LIBRE (KG)
    #
    # carga_kg = Σ stock_actual × peso del producto
    # libre_kg = capacidad - carga_kg
    #
    # Productos sin peso (antiguos) cuentan 0 kg.
    # ============================================================

    @staticmethod
    async def enriquecer(
        racks: List[Dict[str, Any]]
    ) -> List[Dict[str, Any]]:

        if not racks:
            return []

        ids = [
            _id_rack(rack)
            for rack in racks
            if _id_rack(rack)
        ]

        inventarios = await (
            InventarioRepository()
            .obtener_por_racks(
                ids
            )
        )

        productos = await (
            get_database()["productos"]
            .find(
                {
                    "id_producto": {
                        "$in": list(
                            {
                                inventario["id_producto"]
                                for inventario in inventarios
                            }
                        )
                    }
                },
                {
                    "_id": 0,
                    "id_producto": 1,
                    "peso": 1
                }
            )
            .to_list(
                length=None
            )
        )

        pesos = {
            producto["id_producto"]:
                float(producto.get("peso") or 0)
            for producto in productos
        }

        cargas: Dict[str, float] = {}

        for inventario in inventarios:

            cargas[inventario["id_rack"]] = (
                cargas.get(
                    inventario["id_rack"],
                    0.0
                )
                + float(
                    inventario.get("stock_actual") or 0
                )
                * pesos.get(
                    inventario["id_producto"],
                    0.0
                )
            )

        resultado = []

        for rack in racks:

            item = dict(rack)

            if "id_rack" not in item:
                item["id_rack"] = _id_rack(rack)

            carga = round(
                cargas.get(
                    item["id_rack"],
                    0.0
                ),
                3
            )

            item["carga_kg"] = carga

            item["libre_kg"] = round(
                float(
                    item.get(
                        "capacidad",
                        0
                    )
                )
                - carga,
                3
            )

            resultado.append(item)

        return resultado


    @staticmethod
    async def enriquecer_uno(
        rack: Dict[str, Any]
    ) -> Dict[str, Any]:

        return (
            await RackService.enriquecer(
                [rack]
            )
        )[0]


    # ============================================================
    # MOTIVO POR EL QUE UN PRODUCTO NO CABE EN UN RACK
    #
    # rack: ya enriquecido (carga_kg / libre_kg).
    # Devuelve None si cabe.
    #
    # 1. rack DISPONIBLE (si exigir_disponible)
    # 2. cantidad × peso <= libre_kg
    # 3. producto refrigerado: el rango del rack debe
    #    caber dentro del rango del producto
    # ============================================================

    @staticmethod
    def motivo_no_cabe(
        rack: Dict[str, Any],
        producto: Dict[str, Any],
        cantidad: float,
        exigir_disponible: bool = True
    ) -> Optional[str]:

        codigo = rack.get(
            "codigo",
            rack["id_rack"]
        )

        if (
            exigir_disponible
            and
            rack.get("estado") != "DISPONIBLE"
        ):

            return (
                f"El rack {codigo} no está "
                "DISPONIBLE (estado: "
                f"{rack.get('estado')})"
            )

        carga = (
            float(cantidad)
            * float(producto.get("peso") or 0)
        )

        if carga > 0 and carga > rack["libre_kg"] + 1e-9:

            return (
                f"Capacidad insuficiente en el rack "
                f"{codigo}. Libre: "
                f"{_kg(max(rack['libre_kg'], 0))} kg. "
                f"Carga a ingresar: {_kg(carga)} kg"
            )

        if producto.get("requiere_refrigeracion"):

            r_min = rack.get("temperatura_min")
            r_max = rack.get("temperatura_max")
            p_min = producto.get(
                "temperatura_min_almacenamiento"
            )
            p_max = producto.get(
                "temperatura_max_almacenamiento"
            )

            if r_min is None or r_max is None:

                return (
                    f"El producto requiere refrigeración "
                    f"y el rack {codigo} no tiene "
                    "temperatura definida"
                )

            if (
                (p_min is not None and r_min < p_min)
                or
                (p_max is not None and r_max > p_max)
            ):

                return (
                    f"La temperatura del rack {codigo} "
                    f"({_kg(r_min)} a {_kg(r_max)} °C) no cabe "
                    "en el rango del producto "
                    f"({_kg(p_min)} a {_kg(p_max)} °C)"
                )

        return None


    # ============================================================
    # VALIDAR ASIGNACION (409)
    #
    # Usado por: crear inventario, ingreso de recepción,
    # resolver evaluación y entradas de stock.
    # ============================================================

    @staticmethod
    async def validar_asignacion(
        rack: Dict[str, Any],
        producto: Dict[str, Any],
        cantidad: float,
        exigir_disponible: bool = True
    ) -> Dict[str, Any]:

        rack = await (
            RackService.enriquecer_uno(
                rack
            )
        )

        motivo = RackService.motivo_no_cabe(
            rack,
            producto,
            cantidad,
            exigir_disponible
        )

        if motivo:

            raise HTTPException(
                status_code=409,
                detail=motivo
            )

        return rack


    # ============================================================
    # CREAR
    # ============================================================

    async def crear_rack(
        self,
        data: RackCreate
    ):
        zona = (
            await self.zona_repository.obtener_por_id(
                data.id_zona
            )
        )

        if not zona:
            raise HTTPException(
                status_code=404,
                detail="Zona no encontrada"
            )

        # --------------------------------------------------------
        # NIVEL DENTRO DE LOS NIVELES DE LA ZONA
        # --------------------------------------------------------

        niveles = int(
            zona.get("capacidad") or 0
        )

        if data.nivel > niveles:
            raise HTTPException(
                status_code=409,
                detail=(
                    f"La zona solo tiene {niveles} "
                    f"nivel(es); no existe el nivel {data.nivel}"
                )
            )

        # --------------------------------------------------------
        # UN RACK POR NIVEL
        # --------------------------------------------------------

        racks_zona = (
            await self.repository.obtener_por_zona(
                data.id_zona
            )
        )

        if any(
            rack.get("nivel") == data.nivel
            for rack in racks_zona
        ):
            raise HTTPException(
                status_code=409,
                detail=(
                    f"Ya existe un rack en el nivel "
                    f"{data.nivel} de esta zona"
                )
            )

        codigo = data.codigo.strip().upper()

        if any(
            rack.get("codigo") == codigo
            for rack in racks_zona
        ):
            raise HTTPException(
                status_code=409,
                detail=(
                    "Ya existe un rack con ese "
                    "código en la zona"
                )
            )

        # --------------------------------------------------------
        # TEMPERATURA: SOLO ZONAS REFRIGERADAS
        # --------------------------------------------------------

        tiene_temperatura = (
            data.temperatura_min is not None
            or data.temperatura_max is not None
        )

        if zona.get("refrigerada"):

            if (
                data.temperatura_min is None
                or data.temperatura_max is None
            ):
                raise HTTPException(
                    status_code=422,
                    detail=(
                        "La zona es refrigerada: indique "
                        "temperatura_min y temperatura_max "
                        "del rack"
                    )
                )

        elif tiene_temperatura:

            raise HTTPException(
                status_code=409,
                detail=(
                    "Solo los racks de zonas refrigeradas "
                    "tienen temperatura"
                )
            )

        ahora = datetime.now(
            timezone.utc
        )

        rack = {
            "id_rack":
                str(uuid4()),

            "id_zona":
                data.id_zona,

            "codigo":
                codigo,

            "nivel":
                data.nivel,

            "capacidad":
                data.capacidad,

            "temperatura_min":
                data.temperatura_min,

            "temperatura_max":
                data.temperatura_max,

            "estado":
                data.estado.value,

            "fecha_creacion":
                ahora,

            "fecha_actualizacion":
                ahora
        }

        return await self.enriquecer_uno(
            await self.repository.crear(
                rack
            )
        )


    # ============================================================
    # OBTENER RACKS
    #
    # ids_zona: alcance del usuario (None = sin filtro).
    # ============================================================

    async def obtener_racks(
        self,
        ids_zona: Optional[Set[str]] = None
    ):

        if ids_zona is None:

            racks = await (
                self.repository.obtener_todos()
            )

        elif not ids_zona:

            return []

        else:

            racks = await (
                self.repository.obtener_por_zonas(
                    list(ids_zona)
                )
            )

        return await self.enriquecer(
            racks
        )


    async def obtener_rack(
        self,
        id_rack: str
    ):
        rack = (
            await self.repository.obtener_por_id(
                id_rack
            )
        )

        if not rack:
            raise HTTPException(
                status_code=404,
                detail="Rack no encontrado"
            )

        return await self.enriquecer_uno(
            rack
        )


    async def obtener_racks_zona(
        self,
        id_zona: str
    ):
        zona = (
            await self.zona_repository.obtener_por_id(
                id_zona
            )
        )

        if not zona:
            raise HTTPException(
                status_code=404,
                detail="Zona no encontrada"
            )

        return await self.enriquecer(
            await self.repository.obtener_por_zona(
                id_zona
            )
        )


    # ============================================================
    # RACKS DISPONIBLES PARA UN PRODUCTO
    #
    # Racks del almacén donde caben `cantidad` unidades
    # del producto (estado, kg y temperatura).
    # Sin producto: solo racks DISPONIBLES.
    # ============================================================

    async def obtener_disponibles(
        self,
        id_almacen: str,
        producto: Optional[Dict[str, Any]] = None,
        cantidad: float = 0
    ):

        zonas = await (
            self.zona_repository
            .obtener_por_almacenes(
                [id_almacen]
            )
        )

        nombres_zona = {
            (zona.get("id") or zona.get("id_zona")):
                zona.get("nombre")
            for zona in zonas
        }

        if not nombres_zona:
            return []

        racks = await self.enriquecer(
            await self.repository.obtener_por_zonas(
                list(nombres_zona.keys())
            )
        )

        disponibles = []

        for rack in racks:

            if self.motivo_no_cabe(
                rack,
                producto or {},
                cantidad
            ):
                continue

            rack["id_almacen"] = id_almacen

            rack["nombre_zona"] = nombres_zona.get(
                rack.get("id_zona")
            )

            disponibles.append(rack)

        disponibles.sort(
            key=lambda r: (
                r.get("nombre_zona") or "",
                r.get("nivel") or 0
            )
        )

        return disponibles


    # ============================================================
    # ACTUALIZAR (OPERARIO): estado y temperatura
    # ============================================================

    async def actualizar_rack(
        self,
        id_rack: str,
        data: RackUpdate
    ):
        rack_actual = (
            await self.repository.obtener_por_id(
                id_rack
            )
        )

        if not rack_actual:
            raise HTTPException(
                status_code=404,
                detail="Rack no encontrado"
            )

        datos = data.model_dump(
            exclude_unset=True
        )

        if "estado" in datos:

            if datos["estado"] is None:
                datos.pop("estado")
            else:
                datos["estado"] = datos["estado"].value

        if (
            "temperatura_min" in datos
            or "temperatura_max" in datos
        ):

            zona = (
                await self.zona_repository.obtener_por_id(
                    rack_actual["id_zona"]
                )
            )

            if not (zona or {}).get("refrigerada"):
                raise HTTPException(
                    status_code=409,
                    detail=(
                        "Solo los racks de zonas refrigeradas "
                        "tienen temperatura"
                    )
                )

            t_min = datos.get(
                "temperatura_min",
                rack_actual.get("temperatura_min")
            )

            t_max = datos.get(
                "temperatura_max",
                rack_actual.get("temperatura_max")
            )

            if t_min is None or t_max is None:
                raise HTTPException(
                    status_code=422,
                    detail=(
                        "Indique temperatura_min "
                        "y temperatura_max"
                    )
                )

            if t_min > t_max:
                raise HTTPException(
                    status_code=422,
                    detail=(
                        "La temperatura mínima no puede "
                        "ser mayor que la máxima"
                    )
                )

        if not datos:
            return await self.enriquecer_uno(
                rack_actual
            )

        return await self.enriquecer_uno(
            await self.repository.actualizar(
                id_rack,
                datos
            )
        )


    async def eliminar_rack(
        self,
        id_rack: str
    ):
        rack = (
            await self.repository.obtener_por_id(
                id_rack
            )
        )

        if not rack:
            raise HTTPException(
                status_code=404,
                detail="Rack no encontrado"
            )

        # --------------------------------------------------------
        # NO BORRAR RACKS CON INVENTARIO
        # --------------------------------------------------------

        inventarios = await (
            InventarioRepository()
            .obtener_por_rack(
                id_rack
            )
        )

        if inventarios:
            raise HTTPException(
                status_code=409,
                detail=(
                    "El rack tiene inventarios; "
                    "no puede eliminarse"
                )
            )

        eliminado = (
            await self.repository.eliminar(
                id_rack
            )
        )

        return {
            "mensaje":
                "Rack eliminado correctamente",

            "eliminado":
                eliminado
        }

app/services/recepcion_mercaderia_servic.source:
from fastapi import HTTPException

from app.database.mongodb import get_database

from app.dto.auth_dto import (
    UsuarioActual
)

from app.dto.recepcion_mercaderia_dto import (
    RecepcionMercaderiaCreate
)

from app.repositories.recepcion_mercaderia_repository import (
    RecepcionMercaderiaRepository
)

from app.repositories.orden_reposicion_repository import (
    OrdenReposicionRepository
)

from app.repositories.detalle_reposicion_repository import (
    DetalleReposicionRepository
)

from app.repositories.detalle_recepcion_repository import (
    DetalleRecepcionRepository
)

from app.repositories.rack_repository import (
    RackRepository
)

from app.services.acceso_service import (
    AccesoService
)

from app.services.detalle_recepcion_service import (
    DetalleRecepcionService
)

from app.services.rack_service import (
    RackService
)


class RecepcionMercaderiaService:

    def __init__(self):
        self.repository = RecepcionMercaderiaRepository()
        self.orden_repository = OrdenReposicionRepository()
        self.detalle_repository = DetalleReposicionRepository()
        self.detalle_recepcion_repository = (
            DetalleRecepcionRepository()
        )
        self.detalle_recepcion_service = (
            DetalleRecepcionService()
        )

    async def crear(
        self,
        data: RecepcionMercaderiaCreate,
        user: UsuarioActual
    ):

        orden = await self.orden_repository.obtener_por_id(
            data.id_orden_reposicion
        )

        if (
            not orden
            or orden.get("id_empresa") != user.id_empresa
        ):
            raise HTTPException(
                status_code=404,
                detail="Orden no encontrada"
            )

        # ----------------------------------------------------
        # Solo OPERARIO, sobre órdenes de su almacén.
        # id_operario se fuerza al del token.
        # ----------------------------------------------------

        if orden.get("id_almacen") != user.id_almacen:

            raise HTTPException(
                status_code=403,
                detail="La orden no es de su almacén"
            )

        data.id_operario = user.id_operario

        if orden["estado"] not in [
            "ENVIADA",
            "PARCIAL"
        ]:
            raise HTTPException(
                status_code=409,
                detail=(
                    "La orden debe estar ENVIADA "
                    "o PARCIAL para recibir mercancía"
                )
            )

        detalles = (
            await self.detalle_repository.obtener_por_orden(
                data.id_orden_reposicion
            )
        )

        if not detalles:
            raise HTTPException(
                status_code=409,
                detail=(
                    "La orden no contiene productos"
                )
            )

        # Cada detalle debe pertenecer a la orden
        ids_detalle_orden = {
            detalle["id_detalle_reposicion"]
            for detalle in detalles
        }

        for detalle in data.detalles:

            if (
                detalle.id_detalle_reposicion
                not in ids_detalle_orden
            ):
                raise HTTPException(
                    status_code=400,
                    detail=(
                        "El detalle de reposición "
                        f"{detalle.id_detalle_reposicion} "
                        "no pertenece a la orden"
                    )
                )

        db = get_database()

        operario = await db["operarios"].find_one(
            {"id_operario": data.id_operario},
            {"_id": 0}
        )

        if (
            not operario
            or operario.get("id_empresa") != user.id_empresa
        ):
            raise HTTPException(
                status_code=404,
                detail="Operario no encontrado"
            )

        if operario.get("estado") != "ACTIVO":
            raise HTTPException(
                status_code=409,
                detail="El operario está inactivo"
            )

        if (
            operario.get("id_almacen")
            != orden["id_almacen"]
        ):
            raise HTTPException(
                status_code=400,
                detail=(
                    "El operario no pertenece "
                    "al almacén de la orden"
                )
            )

        # ----------------------------------------------------
        # PRE-VALIDACION (antes de crear nada)
        #
        # - inventario del producto de la línea, dentro
        #   del almacén del operario
        # - temperatura obligatoria si el producto es
        #   refrigerado (422)
        # - rack DISPONIBLE, con kg libres para todo lo
        #   aceptado en esta recepción y temperatura
        #   compatible (409)
        # ----------------------------------------------------

        detalles_orden = {
            detalle["id_detalle_reposicion"]: detalle
            for detalle in detalles
        }

        racks: dict = {}

        for detalle in data.detalles:

            inventario = await (
                AccesoService.verificar_inventario(
                    user,
                    detalle.id_inventario
                )
            )

            producto = await db["productos"].find_one(
                {
                    "id_producto":
                        detalles_orden[
                            detalle.id_detalle_reposicion
                        ]["id_producto"]
                },
                {"_id": 0}
            ) or {}

            if (
                inventario["id_producto"]
                != producto.get("id_producto")
            ):
                raise HTTPException(
                    status_code=400,
                    detail=(
                        "El inventario seleccionado "
                        "no corresponde al producto "
                        "de la orden"
                    )
                )

            if (
                producto.get("requiere_refrigeracion")
                and detalle.temperatura_recepcion is None
            ):
                raise HTTPException(
                    status_code=422,
                    detail=(
                        "Indique la temperatura de recepción: "
                        f"{producto.get('nombre')} es refrigerado"
                    )
                )

            if detalle.estado_recepcion.value == "EN_EVALUACION":
                continue

            aceptada = (
                detalle.cantidad_recibida
                - detalle.cantidad_rechazada
            )

            if aceptada <= 0:
                continue

            id_rack = inventario["id_rack"]

            if id_rack not in racks:

                racks[id_rack] = await (
                    RackService.enriquecer_uno(
                        await RackRepository.obtener_por_id(
                            id_rack
                        )
                    )
                )

            motivo = RackService.motivo_no_cabe(
                racks[id_rack],
                producto,
                aceptada
            )

            if motivo:
                raise HTTPException(
                    status_code=409,
                    detail=motivo
                )

            # Descontar para las siguientes líneas del mismo rack
            racks[id_rack]["libre_kg"] -= (
                aceptada
                * float(producto.get("peso") or 0)
            )

        recepcion = await self.repository.crear(
            data.model_dump()
        )

        for detalle in data.detalles:
            await self.detalle_recepcion_service.crear(
                recepcion["id_recepcion"],
                detalle,
                user
            )

        recepcion["detalles"] = await (
            self.detalle_recepcion_repository
            .obtener_por_recepcion(
                recepcion["id_recepcion"]
            )
        )

        return recepcion

    async def obtener_todos(self):
        recepciones = await self.repository.obtener_todos()
        return await self._incluir_detalles(recepciones)

    async def obtener_por_id(self, id_recepcion):

        recepcion = await self.repository.obtener_por_id(
            id_recepcion
        )

        if not recepcion:
            raise HTTPException(
                status_code=404,
                detail="Recepción no encontrada"
            )

        recepcion["detalles"] = await (
            self.detalle_recepcion_repository
            .obtener_por_recepcion(id_recepcion)
        )
        return recepcion

    async def obtener_por_orden(self, id_orden):
        recepciones = await self.repository.obtener_por_orden(
            id_orden
        )
        return await self._incluir_detalles(recepciones)

    async def obtener_por_operario(self, id_operario):
        recepciones = await self.repository.obtener_por_operario(
            id_operario
        )
        return await self._incluir_detalles(recepciones)

    async def obtener_por_ordenes(self, ids_orden):
        recepciones = await self.repository.obtener_por_ordenes(
            ids_orden
        )
        return await self._incluir_detalles(recepciones)

    async def _incluir_detalles(self, recepciones):
        for recepcion in recepciones:
            recepcion["detalles"] = await (
                self.detalle_recepcion_repository
                .obtener_por_recepcion(
                    recepcion["id_recepcion"]
                )
            )
        return recepciones

